                // ===== GAME STATE =====
                let gameState = "SPLASH";
                let player = {};
                let keysHeld = {}, directionHistory = [], moveInterval = null, lastMoveTime = 0;
                window._pendingLevelUpCount = 0;
                let npcMoveInterval = null;
                const NPC_MOVE_SPEED = 500; // ms per step
                let currentMapId = "", currentMap = [], npcs = [], currentDecos = [], currentChests = [];
                let currentEnemy = null, enemyHp = 0, enemyMaxHp = 0, battleMenuIndex = 0;
                let isPlayerTurn = true, battleLocked = false, bossPhase = 0;
                let hasLostToBoss = false; // Track if player lost to boss (skip pre-battle dialog on retry)
                let msgQueue = [], isTyping = false, fullText = "", typeIndex = 0;
                let currentMsgCallback = null, msgLocked = false, typeTimer = null;
                let enterBlocked = false; // Debounce für Enter-Taste (verhindert Spam)
                let contractTypeTimeouts = []; // Für Contract-TypeWrite-Timeouts (Reset-BUGFIX)
                let isTransitioning = false, transitionTimeout = null;
                // Hält die beim Laden wiederherzustellende Spielerposition,
                // damit actuallyLoadMap() nicht auf den Map-Startpunkt zurücksetzt.
                let pendingLoadPos = null; // { mapId, x, y, facing } oder null
                let isBattleStarting = false, battleStartTimeout = null;
                let vsFadeOutTimeout = null; // Timer für das Fade-Ausblenden des VS-Splash
                let defeatedEnemies = new Set();
                let openedChests = new Set();
                let battleCount = 0, chestCount = 0;
                let nearbyNPC = null, nearbyChest = null;
                let turnIndicatorTimeout = null;
                let metNPCs = [];
                let playerGender = "m", playerDept = "einkauf";
                let minimapVisible = false;
                let godMode = false;
                let cheatConsoleVisible = false;

                // Movement state (FIXED)
                let isMoving = false;
                let lastMoveTimestamp = 0;
                const MOVE_DURATION = 104; // INPUT FIX: gleichmäßiger Tile-Step, weniger Speed-Schwankung
                const MOVE_COOLDOWN = 92; // INPUT FIX: verhindert Doppel-/Auto-Step durch zu kurzen Cooldown
                const MOVE_LOOP_BUFFER = 12;
                const MOVE_KEY_DIRS = {
                    ArrowUp: [0, -1], ArrowDown: [0, 1], ArrowLeft: [-1, 0], ArrowRight: [1, 0],
                    KeyW: [0, -1], KeyS: [0, 1], KeyA: [-1, 0], KeyD: [1, 0]
                };

                function getMoveInputCode(e) {
                    if (!e) return null;
                    if (MOVE_KEY_DIRS[e.code]) return e.code;
                    // Fallback für ältere Browser / synthetische Events
                    const keyMap = { w: 'KeyW', W: 'KeyW', a: 'KeyA', A: 'KeyA', s: 'KeyS', S: 'KeyS', d: 'KeyD', D: 'KeyD' };
                    if (MOVE_KEY_DIRS[e.key]) return e.key;
                    return keyMap[e.key] || null;
                }

                function pressMoveInput(code) {
                    if (!code || !MOVE_KEY_DIRS[code]) return;
                    keysHeld[code] = true;
                    directionHistory = directionHistory.filter(k => k !== code);
                    directionHistory.push(code);
                }

                function releaseMoveInput(code) {
                    if (!code) return;
                    delete keysHeld[code];
                    directionHistory = directionHistory.filter(k => k !== code);
                    if (!Object.keys(keysHeld).some(k => MOVE_KEY_DIRS[k])) stopMoveLoop();
                }

                function clearMoveInputState() {
                    keysHeld = {};
                    directionHistory = [];
                    stopMoveLoop();
                }

                const DEPT_NAMES = { einkauf: "Einkauf", verkauf: "Verkauf", zentrale: "Zentrale", verwaltung: "Verwaltung" };
                const GENDER_SPRITES = { m: "🧑‍💼", f: "👩‍💼" };
                const GENDER_TITLES = { m: "Auszubildender", f: "Auszubildende" };

                // ===== SMOOTH MOVEMENT - PROFESSIONAL DIRECTION SYSTEM =====
                function smoothMove(dx, dy) {
                    const now = performance.now();
                    if (now - lastMoveTimestamp < MOVE_COOLDOWN) return false;
                    if (isMoving || gameState !== "MAP" || isTransitioning || isBattleStarting) return false;

                    const nx = player.x + dx;
                    const ny = player.y + dy;

                    const mapCols = currentMap[0]?.length || 0;
                    const mapRows = currentMap.length;
                    if (nx < 0 || nx >= mapCols || ny < 0 || ny >= mapRows) return false;

                    // Professional direction system - only LEFT/RIGHT rotations
                    if (dx < 0) {
                        player.facing = "left";
                    } else if (dx > 0) {
                        player.facing = "right";
                    }
                    // Vertical movement does NOT change player direction

                    const tile = currentMap[ny] ? currentMap[ny][nx] : 1;
                    const tileData = TILES[tile] || {};

                    if (tileData.block) return false;

                    const npcHit = npcs.find(n => n.x === nx && n.y === ny);
                    if (npcHit) { interactNPC(npcHit); return false; }

                    // Chest collision (FIXED - blockiert)
                    const chestHit = currentChests.find(c => c.x === nx && c.y === ny && !c.opened);
                    if (chestHit) {
                        const idx = currentChests.indexOf(chestHit);
                        const chestEl = chestLayer?.querySelector(`[data-index="${idx}"]`);
                        if (chestEl) openChest(chestHit, chestEl);
                        return false;
                    }

                    // Door check (FIXED - durch Berührung)
                    if (tileData.name === "door_normal" || tileData.name === "door_boss") {
                        handleDoor(nx, ny, tileData);
                        return false;
                    }

                    isMoving = true;
                    lastMoveTimestamp = now;
                    player.x = nx;
                    player.y = ny;
                    if (typeof checkSecretDocumentTile === "function") checkSecretDocumentTile();
                    if (typeof checkSecretRoomEntrance === "function") checkSecretRoomEntrance();

                    playerEl.classList.add("walking");
                    placeMapElement(playerEl, player.x, player.y, "player", `left ${MOVE_DURATION}ms linear, top ${MOVE_DURATION}ms linear`);

                    updateCamera();
                    startCameraLoop(); // PERF: Kamera nur nach Bewegung animieren, nicht dauerhaft
                    queueMinimapUpdate(); // BUGFIX: Minimap bei Spielerbewegung aktualisieren

                    setTimeout(() => {
                        isMoving = false;
                        playerEl.classList.remove("walking");
                        playerEl.style.transition = "";
                        checkNearbyInteractables();
                    }, MOVE_DURATION);

                    return true;
                }

                function tryMove(dx, dy) {
                    if (isMoving) return;
                    smoothMove(dx, dy);
                }

                // ===== CHEST SYSTEM =====
                function spawnChests() {
                    if (!chestLayer) return;
                    chestLayer.innerHTML = "";
                    currentChests.forEach((chest, i) => {
                        const chestKey = `${currentMapId}_${chest.x}_${chest.y}`;
                        if (openedChests.has(chestKey)) chest.opened = true;
                        const el = document.createElement("div");
                        el.className = "map-chest" + (chest.opened ? " opened" : "");
                        el.innerHTML = `<div class="chest-glow"></div><div class="chest-sprite">${chest.opened ? "📭" : (chest.type === "rare" ? "🎁" : "📦")}</div>`;
                        placeMapElement(el, chest.x, chest.y, "chest");
                        el.dataset.index = i;
                        el.addEventListener("click", () => {
                            const dist = Math.abs(player.x - chest.x) + Math.abs(player.y - chest.y);
                            if (dist <= 1 && !chest.opened && gameState === "MAP") openChest(chest, el);
                        });
                        chestLayer.appendChild(el);
                    });
                    parseEmojis(chestLayer);
                }


                function playChestOpenAnimation(el) {
                    if (!el) return;
                    el.classList.add("opening");
                    const glow = document.createElement("div");
                    glow.className = "chest-loot-glow-v518";
                    el.appendChild(glow);
                    for (let i = 0; i < 12; i++) {
                        const spark = document.createElement("span");
                        spark.className = "chest-spark-v518";
                        const angle = (Math.PI * 2 * i / 12) + Math.random() * .35;
                        const dist = 22 + Math.random() * 42;
                        spark.style.setProperty("--dx", Math.cos(angle) * dist + "px");
                        spark.style.setProperty("--dy", Math.sin(angle) * dist - 28 + "px");
                        spark.style.animationDelay = (i * 0.025).toFixed(2) + "s";
                        el.appendChild(spark);
                        setTimeout(() => spark.remove(), 1000);
                    }
                    setTimeout(() => {
                        el.classList.remove("opening");
                        if (glow.parentElement) glow.remove();
                    }, 780);
                }

                function openChest(chest, el) {
                    if (chest.opened) return;

                    chest.opened = true;
                    chestCount++;
                    if (typeof window._trackChestOpen === 'function') window._trackChestOpen();
                    const chestKey = `${currentMapId}_${chest.x}_${chest.y}`;
                    openedChests.add(chestKey);

                    playChestOpenAnimation(el);
                    setTimeout(() => {
                        el.classList.add("opened");
                        const sprite = el.querySelector(".chest-sprite");
                        if (sprite) sprite.innerText = "📭";
                    }, 620);

                    let loot;
                    if (chest.type === "rare") {
                        const rareItems = CHEST_ITEMS.filter(i => i.type === "gold" && i.amount >= 50 || i.type === "item" || i.type === "atk");
                        loot = rareItems[Math.floor(Math.random() * rareItems.length)];
                    } else {
                        loot = CHEST_ITEMS[Math.floor(Math.random() * CHEST_ITEMS.length)];
                    }

                    let lootMsg = "";
                    if (loot.type === "gold") {
                        player.gold += loot.amount;
                        lootMsg = `${loot.icon} +${loot.amount} Gold!`;
                    } else if (loot.type === "item") {
                        const itemData = SHOP_ITEMS.find(s => s.id === loot.itemId);
                        if (itemData) {
                            const existing = player.inventory.find(i => i.id === loot.itemId);
                            if (existing) existing.count++;
                            else player.inventory.push({ id: loot.itemId, name: itemData.icon + " " + itemData.name, heal: itemData.heal, mpHeal: itemData.mpHeal || 0, count: 1 });
                        }
                        lootMsg = `${loot.icon} ${loot.name} erhalten!`;
                    } else if (loot.type === "atk") {
                        player.atk += loot.amount;
                        lootMsg = `${loot.icon} +${loot.amount} Angriff!`;
                    } else if (loot.type === "hp") {
                        player.maxHp += loot.amount;
                        player.hp += loot.amount;
                        lootMsg = `${loot.icon} +${loot.amount} Max HP!`;
                    } else if (loot.type === "exp") {
                        player.exp += loot.amount;
                        checkLevelUp();
                        lootMsg = `${loot.icon} +${loot.amount} EXP!`;
                    }

                    updateHUD();
                    showMessage(`📦 Truhe geöffnet! ${lootMsg}`, "📦 Loot", "📦");
                }

                // Hide Easter UI when player is near (so it doesn't block the view)
                function updateEasterUIVisibility() {
                    const easterUI = document.getElementById("easter-event-ui");
                    if (!easterUI || !easterEventState.active) return;

                    // Get viewport center to check if player is in top area
                    const viewportWidth = 27 * 32; // VIEW_COLS * TILE
                    const viewportHeight = 17 * 32; // VIEW_ROWS * TILE
                    
                    // Calculate player's screen position
                    const playerScreenX = player.x * 32 - cameraX;
                    const playerScreenY = player.y * 32 - cameraY;

                    // If player is in the top center area (where the UI is), hide it partially
                    const isInUIArea = playerScreenY < 150 && playerScreenX > viewportWidth * 0.3 && playerScreenX < viewportWidth * 0.7;
                    
                    if (isInUIArea) {
                        easterUI.classList.add("hidden-for-player");
                    } else {
                        easterUI.classList.remove("hidden-for-player");
                    }
                }

                function checkNearbyInteractables() {
                    checkNearbyNPC();
                    checkNearbyChest();
                    checkNearbyEasterEgg();
                    updateEasterUIVisibility();
                }

                function checkNearbyChest() {
                    nearbyChest = null;
                    for (const chest of currentChests) {
                        if (chest.opened) continue;
                        const dist = Math.abs(player.x - chest.x) + Math.abs(player.y - chest.y);
                        if (dist === 1) { nearbyChest = chest; break; }
                    }

                    if (nearbyChest && !nearbyNPC) {
                        const textEl = document.getElementById("interaction-text");
                        const iconEl = document.getElementById("interaction-icon");
                        if (textEl) textEl.innerText = "Öffnen";
                        if (iconEl) iconEl.innerText = "📦";
                        interactionHint.classList.remove("mode-attack", "mode-shop", "mode-talk", "mode-default");
                        interactionHint.classList.add("visible", "mode-chest");
                    }
                }

                // ===== EASTER EVENT SYSTEM =====
                function spawnEasterEggs() {
                    if (!easterEggLayer) return;
                    easterEggLayer.innerHTML = "";
                    currentEasterEggs = [];
                    if (!easterEventState.active || easterEventState.completed) return;
                    const mapEggs = EASTER_EGGS[currentMapId];
                    if (!mapEggs) return;
                    mapEggs.forEach((egg, i) => {
                        const eggKey = `${currentMapId}_${egg.x}_${egg.y}`;
                        if (easterEventState.collectedEggs.includes(eggKey)) return;
                        currentEasterEggs.push({ ...egg, key: eggKey });
                        const el = document.createElement("div");
                        el.className = "map-easter-egg";
                        el.innerHTML = `<div class="easter-egg-glow"></div><div class="easter-egg-sprite">🥚</div>`;
                        placeMapElement(el, egg.x, egg.y, "egg");
                        el.dataset.eggKey = eggKey;
                        el.dataset.eggIndex = i;
                        el.addEventListener("click", () => {
                            const dist = Math.abs(player.x - egg.x) + Math.abs(player.y - egg.y);
                            if (dist <= 1 && gameState === "MAP") collectEasterEgg(egg, el, eggKey);
                        });
                        easterEggLayer.appendChild(el);
                    });
                    parseEmojis(easterEggLayer);
                    updateEasterUI();
                }


                function collectEasterEgg(egg, el, eggKey) {
                    if (easterEventState.collectedEggs.includes(eggKey)) return;

                    // Add to collected eggs
                    easterEventState.collectedEggs.push(eggKey);
                    
                    // Play collection animation
                    el.classList.add("collected");
                    el.querySelector(".easter-egg-sprite").innerText = "✨";

                    // Show message
                    showMessage(`🥚 Du hast ein ${egg.name} gefunden!`, "🐇 Osterhase", "🐰");
                    queueMessage(`Hinweis: ${egg.hint}`, "🐇 Osterhase", "🐰");

                    // Update UI
                    updateEasterUI();

                    // Check if all eggs collected
                    if (easterEventState.collectedEggs.length >= easterEventState.totalEggs) {
                        setTimeout(() => {
                            showMessage("🎉 Du hast ALLE Ostereier gefunden! Kehre zu Patrick zurück!", "🐇 Osterhase", "🐰");
                            easterEventState.completed = true;
                            updateEasterUI();
                        }, 1500);
                    }

                    // Play sound effect (visual feedback)
                    const gameWin = document.getElementById("rpg-game-window");
                    if (gameWin) {
                        const spark = document.createElement("div");
                        spark.style.cssText = `
                            position: absolute;
                            left: ${egg.x * TILE + 16}px;
                            top: ${egg.y * TILE}px;
                            font-size: 2rem;
                            pointer-events: none;
                            animation: easterSparkle 1s ease-out forwards;
                            z-index: 100;
                        `;
                        spark.innerText = "✨";
                        gameWin.appendChild(spark);
                        setTimeout(() => spark.remove(), 1000);
                    }

                    // Save progress
                    saveGame();
                }

                function updateEasterUI() {
                    const easterUI = document.getElementById("easter-event-ui");
                    if (!easterUI) return;

                    // Show/hide UI based on event state
                    if (!easterEventState.active) {
                        easterUI.style.display = "none";
                        return;
                    }

                    // Hide UI if quest is fully completed (reward claimed)
                    if (player.questState && player.questState.easterEvent === "completed") {
                        easterUI.style.display = "none";
                        easterUI.classList.remove("complete");
                        return;
                    }

                    easterUI.style.display = "block";

                    // Update progress
                    const countEl = document.getElementById("easter-eggs-count");
                    const totalEl = document.getElementById("easter-eggs-total");
                    const fillEl = document.getElementById("easter-progress-fill");
                    const hintEl = document.getElementById("easter-event-hint");

                    const collected = easterEventState.collectedEggs.length;
                    const total = easterEventState.totalEggs;

                    if (countEl) countEl.innerText = collected;
                    if (totalEl) totalEl.innerText = total;
                    if (fillEl) fillEl.style.width = `${(collected / total) * 100}%`;

                    // Update hint
                    if (hintEl) {
                        if (easterEventState.completed) {
                            hintEl.innerText = "✅ Kehre zu Patrick zurück!";
                            easterUI.classList.add("complete");
                        } else {
                            hintEl.innerText = `Noch ${total - collected} Eier versteckt!`;
                        }
                    }
                }

                function startEasterEvent() {
                    easterEventState.active = true;
                    easterEventState.collectedEggs = [];
                    easterEventState.completed = false;
                    updateEasterUI();
                    spawnEasterEggs();
                }

                function checkNearbyEasterEgg() {
                    if (!easterEventState.active || easterEventState.completed) return;

                    for (const egg of currentEasterEggs) {
                        if (easterEventState.collectedEggs.includes(egg.key)) continue;
                        const dist = Math.abs(player.x - egg.x) + Math.abs(player.y - egg.y);
                        if (dist <= 1) {
                            // Show interaction hint
                            const textEl = document.getElementById("interaction-text");
                            const iconEl = document.getElementById("interaction-icon");
                            if (textEl) textEl.innerText = "Sammeln";
                            if (iconEl) iconEl.innerText = "🥚";
                            interactionHint.classList.remove("mode-attack", "mode-shop", "mode-talk", "mode-chest", "mode-default");
                            interactionHint.classList.add("visible", "mode-easter-egg");
                            return egg;
                        }
                    }
                    return null;
                }

                // Patrick (Ausbilder) Easter Quest Choice Handler
                function openPatrickEasterChoice(npc) {
                    if (typeof window.showChoice !== "function") return;

                    if (!player.questState) player.questState = {};
                    const questState = player.questState.easterEvent || null;

                    // Quest not started yet
                    if (questState === null || questState === undefined) {
                        window.showChoice("Hallo! *hust* Ich bin Patrick, dein Ausbilder. Ich habe eine besondere Aufgabe für dich... Es ist Ostern! 🐰 Kannst du mir helfen, die versteckten Ostereier zu finden?", [
                            { label: "Ja, ich helfe gerne!", value: "accept", hint: "🥚" },
                            { label: "Was bekomme ich dafür?", value: "reward", hint: "🎁" },
                            { label: "Nein, keine Zeit.", value: "decline", hint: "❌" }
                        ], npc.name, npc.sprite, (val) => {
                            if (val === "accept") {
                                player.questState.easterEvent = "active";
                                startEasterEvent();
                                showMessage("Wunderbar! Es sind 10 Ostereier im gesamten Büro versteckt. Ich habe eine Anzeige für dich erstellt. Viel Glück! 🐰", npc.name, npc.sprite);
                                queueMessage("Suche in allen Räumen - Büro, Flur, Kantine und Zentrale!", npc.name, npc.sprite);
                            } else if (val === "reward") {
                                showMessage("Wenn du alle Eier findest, bringe ich dir einen speziellen Oster-Skill bei: Oster-Flower-Power! 🌸", npc.name, npc.sprite);
                                queueMessage("Dieser Skill heilt dich und schadet dem Gegner gleichzeitig!", npc.name, npc.sprite);
                                // Re-open the choice
                                setTimeout(() => openPatrickEasterChoice(npc), 500);
                            } else {
                                showMessage("Oh schade... Falls du es dir anders überlegst, bin ich hier.", npc.name, npc.sprite);
                            }
                        });
                    } else if (questState === "active") {
                        // Quest in progress
                        const collected = easterEventState.collectedEggs.length;
                        const total = easterEventState.totalEggs;

                        if (easterEventState.completed) {
                            // All eggs collected - complete quest
                            window.showChoice(`Unglaublich! Du hast alle ${total} Ostereier gefunden! 🎉 Bist du bereit für deine Belohnung?`, [
                                { label: "Ja, her mit dem Skill!", value: "complete", hint: "🌸" }
                            ], npc.name, npc.sprite, (val) => {
                                    if (val === "complete") {
                                        // Mark quest as completed and deactivate the Easter event so the UI no longer appears
                                        player.questState.easterEvent = "completed";
                                        easterEventState.active = false;
                                        updateEasterUI();

                                        // Add the Easter Skill
                                        if (!player.unlockedSkills) player.unlockedSkills = ["tacker", "kaffee", "meeting"];
                                        if (!player.unlockedSkills.includes("oster_power")) {
                                            player.unlockedSkills.push("oster_power");
                                            showMessage("Du hast den exklusiven Skill 'Oster-Flower-Power' gelernt! 🌸✨", "📋 System", "🌸");
                                            queueMessage("Dieser Skill heilt 50% deiner HP und fügt dem Gegner massiven Schaden zu!", "📋 System", "🌸");
                                            queueMessage("Frohe Ostern! 🐰🥚", npc.name, npc.sprite);
                                        } else {
                                            showMessage("Du hast diesen Skill bereits! Hier sind 200 Gold als Bonus! 💰", npc.name, npc.sprite);
                                            player.gold += 200;
                                            updateHUD();
                                        }
                                    }
                            });
                        } else {
                            // Still searching
                            window.showChoice(`Du hast bisher ${collected} von ${total} Ostereiern gefunden. ${collected < total ? `Noch ${total - collected} Eier fehlen!` : 'Alle gefunden!'}`, [
                                { label: "Ich suche weiter!", value: "continue", hint: "🔍" },
                                { label: "Wo sind die Eier?", value: "hint", hint: "💡" }
                            ], npc.name, npc.sprite, (val) => {
                                if (val === "hint") {
                                    showMessage("Die Eier sind im Büro (3), Flur (3), Kantine (2) und in der Zentrale (2) versteckt.", npc.name, npc.sprite);
                                    queueMessage("Schau in jeder Ecke - sie leuchten leicht! 🥚✨", npc.name, npc.sprite);
                                } else {
                                    showMessage("Viel Erfolg! Die Eier warten auf dich! 🐰", npc.name, npc.sprite);
                                }
                            });
                        }
                    } else if (questState === "completed") {
                        showMessage("Danke nochmals für deine Hilfe bei der Ostersuche! Der Oster-Flower-Power Skill wird dir nützlich sein! 🌸🐰", npc.name, npc.sprite);
                    }
                }

                // ===== DOOR SYSTEM (FIXED) =====
                // PATCH J: verbesserte Iso-Tuer - hoeher/breiter, besseres Design,
                //          + Chef-Tuer (boss) edel & + Doppeltuer (double, 2 Tiles breit)
                function isoDoorSvg(x, y, opts) {
                    const ME = window.MapEngineV6;
                    if (!ME) return null;
                    opts = opts || {};
                    const span = opts.double ? 2 : 1;              // PATCH J: Tile-Breite der Tueroeffnung
                    const tw = ME.tileW, th = ME.tileH, zs = ME.zScale;
                    const rawAbs = (gx, gy, gz) => ({ x: (gx - gy) * tw * 0.5, y: (gx + gy) * th * 0.5 - gz * zs });
                    const o0 = rawAbs(x, y, 0);
                    const raw = (gx, gy, gz) => { const p = rawAbs(gx, gy, gz); return { x: p.x - o0.x, y: p.y - o0.y }; };
                    const cols = currentMap[0]?.length || VIEW_COLS, rows = currentMap.length;
                    const onLeft = (x === 0), onRight = (x === cols - 1);
                    const onTop = (y === 0), onBottom = (y === rows - 1);
                    const dh = 1.7; // PATCH J: Tuer etwas hoeher als die Wand-Basis (ragt leicht in den Rahmen)
                    // 4 Eckpunkte der kamerazugewandten Wandflaeche (oben-links,oben-rechts,unten-rechts,unten-links)
                    let q;
                    if (onRight) {
                        q = [raw(x + 1, y, dh), raw(x + 1, y + span, dh), raw(x + 1, y + span, 0), raw(x + 1, y, 0)];
                    } else if (onBottom) {
                        q = [raw(x, y + 1, dh), raw(x + span, y + 1, dh), raw(x + span, y + 1, 0), raw(x, y + 1, 0)];
                    } else if (onLeft) {
                        q = [raw(x + 1, y, dh), raw(x + 1, y + span, dh), raw(x + 1, y + span, 0), raw(x + 1, y, 0)];
                    } else if (onTop) {
                        q = [raw(x, y + 1, dh), raw(x + span, y + 1, dh), raw(x + span, y + 1, 0), raw(x, y + 1, 0)];
                    } else {
                        q = [raw(x, y + 1, dh), raw(x + span, y + 1, dh), raw(x + span, y + 1, 0), raw(x, y + 1, 0)];
                    }
                    const minX = Math.min(...q.map(p => p.x)), minY = Math.min(...q.map(p => p.y));
                    const maxX = Math.max(...q.map(p => p.x)), maxY = Math.max(...q.map(p => p.y));
                    const pad = 4, w = (maxX - minX) + pad * 2, hh = (maxY - minY) + pad * 2;
                    const sh = p => ({ x: p.x - minX + pad, y: p.y - minY + pad });
                    const A = sh(q[0]), B = sh(q[1]), C = sh(q[2]), D = sh(q[3]);
                    const lerp = (p, qq, t) => ({ x: p.x + (qq.x - p.x) * t, y: p.y + (qq.y - p.y) * t });
                    const bilerp = (u, v) => { const top = lerp(A, B, u), bot = lerp(D, C, u); return lerp(top, bot, v); };
                    const ptStr = p => `${p.x.toFixed(1)},${p.y.toFixed(1)}`;
                    const quad = (u0, v0, u1, v1, fill, op) => {
                        const pts = [bilerp(u0, v0), bilerp(u1, v0), bilerp(u1, v1), bilerp(u0, v1)];
                        return `<polygon points="${pts.map(ptStr).join(' ')}" fill="${fill}"${op != null ? ` opacity="${op}"` : ''}/>`;
                    };
                    // ---- Farbpaletten je Tuer-Typ ----
                    let frameOut, frameIn, panelTop, panelBot, knobC, trimC;
                    if (opts.boss) {            // Chef-Tuer: dunkles Edelholz + Gold
                        frameOut = '#1c1208'; frameIn = '#3a2912';
                        panelTop = '#6f4a24'; panelBot = '#3a2410'; // PATCH K: edler/heller
                        knobC = '#ffd768'; trimC = '#caa24a';
                    } else if (opts.bad) {      // Ausgang/Bad-Ending: warnendes Holz
                        frameOut = '#160d05'; frameIn = '#5a3618';
                        panelTop = '#9f6a38'; panelBot = '#4a2a12';
                        knobC = '#ffd27a'; trimC = '#d98a3a';
                    } else {                    // Standard-Tuer
                        frameOut = '#150c06'; frameIn = '#2f1d10';
                        panelTop = '#a06a38'; panelBot = '#5a3417'; // PATCH K: heller
                        knobC = '#f5c356'; trimC = '#9c6a38';
                    }
                    const gid = 'dG_' + x + '_' + y + (opts.double ? 'd' : '') + (opts.boss ? 'b' : '');
                    let svg = '';
                    svg += `<defs><linearGradient id="${gid}" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="${panelTop}"/><stop offset="0.6" stop-color="${panelBot}"/><stop offset="1" stop-color="${panelBot}"/></linearGradient></defs>`;
                    // Rahmen (gesamte Flaeche)
                    svg += quad(0.0, 0.0, 1.0, 1.0, frameOut);          // aeusserer Rahmen
                    svg += quad(0.05, 0.0, 0.95, 1.0, frameIn);         // innerer Rahmen
                    // Lichtschein aus der Oeffnung (fuer Animation)
                    const gl0 = bilerp(0.10, 0.0), gl1 = bilerp(0.90, 0.0), gl2 = bilerp(0.90, 1.0), gl3 = bilerp(0.10, 1.0);
                    svg += `<polygon class="iso-door-glow" points="${ptStr(gl0)} ${ptStr(gl1)} ${ptStr(gl2)} ${ptStr(gl3)}" fill="rgba(255,236,170,0.7)"/>`;

                    // Hilfsfunktion: ein Tuerblatt mit Paneelen zeichnen (u-Bereich uL..uR)
                    const buildLeaf = (uL, uR, knobAtRight) => {
                        const uw = uR - uL;
                        let l = '';
                        l += quad(uL, 0.0, uR, 1.0, `url(#${gid})`);                       // Blatt
                        l += quad(uL, 0.0, uR, 0.05, 'rgba(255,255,255,0.12)');           // Oberkante-Highlight
                        // 2 vertikale Paneele (eingelassen)
                        const p1a = uL + uw * 0.16, p1b = uL + uw * 0.46;
                        const p2a = uL + uw * 0.54, p2b = uL + uw * 0.84;
                        l += quad(p1a, 0.10, p1b, 0.46, 'rgba(0,0,0,0.18)');              // Paneel oben links
                        l += quad(p1a + 0.5/100, 0.115, p1b, 0.45, trimC, 0.25);
                        l += quad(p2a, 0.10, p2b, 0.46, 'rgba(0,0,0,0.18)');              // Paneel oben rechts
                        l += quad(p1a, 0.52, p1b, 0.92, 'rgba(0,0,0,0.18)');             // Paneel unten links
                        l += quad(p2a, 0.52, p2b, 0.92, 'rgba(0,0,0,0.18)');             // Paneel unten rechts
                        // Lichtkante + Schattenkante
                        l += quad(uL, 0.0, uL + uw * 0.10, 1.0, 'rgba(255,255,255,0.08)');
                        l += quad(uR - uw * 0.10, 0.04, uR, 1.0, 'rgba(0,0,0,0.22)');
                        if (opts.boss) {
                            // Goldener Mittel-Trim + Wappenstern (PATCH K: kleiner & mittig)
                            l += quad(uL + uw*0.47, 0.06, uL + uw*0.53, 0.96, trimC, 0.45);
                            const str = bilerp((uL+uR)/2, 0.40);
                            const starSz = Math.max(7, Math.min(13, uw*18));
                            l += `<text x="${str.x.toFixed(1)}" y="${(str.y + starSz*0.35).toFixed(1)}" font-size="${starSz.toFixed(0)}" text-anchor="middle" fill="#ffe08a" opacity="0.95" style="paint-order:stroke;stroke:#7a5512;stroke-width:0.6;">★</text>`;
                        }
                        // Knauf
                        const ku = knobAtRight ? (uR - uw * 0.14) : (uL + uw * 0.14);
                        const kn = bilerp(ku, 0.56);
                        l += `<circle cx="${kn.x.toFixed(1)}" cy="${kn.y.toFixed(1)}" r="${opts.double?2.2:2.8}" fill="${knobC}"/>`;
                        l += `<circle cx="${kn.x.toFixed(1)}" cy="${(kn.y-1).toFixed(1)}" r="${opts.double?1.0:1.3}" fill="rgba(255,255,255,0.5)"/>`;
                        return l;
                    };

                    if (opts.double) {
                        // Zwei Fluegel, oeffnen gegengleich (links->linke Kante, rechts->rechte Kante)
                        const hingeL = bilerp(0.08, 0.50);
                        const hingeR = bilerp(0.92, 0.50);
                        const leafL = buildLeaf(0.08, 0.50, true);   // linker Fluegel, Knauf rechts (Mitte)
                        const leafR = buildLeaf(0.50, 0.92, false);  // rechter Fluegel, Knauf links (Mitte)
                        svg += `<g class="iso-door-leaf iso-door-leaf-l" style="transform-origin:${hingeL.x.toFixed(1)}px ${hingeL.y.toFixed(1)}px;">${leafL}</g>`;
                        svg += `<g class="iso-door-leaf iso-door-leaf-r" style="transform-origin:${hingeR.x.toFixed(1)}px ${hingeR.y.toFixed(1)}px;">${leafR}</g>`;
                    } else {
                        const hinge = bilerp(0.10, 0.50);
                        const leaf = buildLeaf(0.10, 0.90, true);
                        svg += `<g class="iso-door-leaf" style="transform-origin:${hinge.x.toFixed(1)}px ${hinge.y.toFixed(1)}px;">${leaf}</g>`;
                    }
                    return { svg: `<svg width="${w.toFixed(0)}" height="${hh.toFixed(0)}" viewBox="0 0 ${w.toFixed(1)} ${hh.toFixed(1)}" style="position:absolute;left:0;top:0;overflow:visible;pointer-events:none;display:block;" xmlns="http://www.w3.org/2000/svg">${svg}</svg>`,
                             ax: minX - pad, ay: minY - pad };
                }
                // PATCH O: JS-Partikel-System - viele Partikel je nach Map-Thema
                let fxLayerNear = null, fxLayerFar = null; // PATCH P: Parallax-Layer-Refs
                function spawnMapParticles(mapId) {
                    const host = document.getElementById("rpg-fx-particles");
                    if (!host) return;
                    // PATCH Q: alte Partikel-Layer sanft ausblenden statt hart entfernen
                    Array.from(host.children).forEach(old => {
                        old.classList.add("fx-fading-out");
                        setTimeout(() => { if (old.parentElement) old.remove(); }, 650);
                    });
                    fxLayerNear = null; fxLayerFar = null;
                    const bvParticleSettings = window.BV_SETTINGS || {};
                    // Bugfix v7.10.1: Performance/low-quality darf Partikel nicht komplett entfernen.
                    // Nur wenn Partikel explizit aus sind oder Reduced-Motion aktiv ist, werden sie wirklich deaktiviert.
                    if (bvParticleSettings.particles === false || bvParticleSettings.reducedMotion === true) return;
                    const lowParticleMode = bvParticleSettings.performance === "performance" || document.getElementById("rpg-game-window")?.classList.contains("map-low-quality");
                    // PATCH P: 2 Tiefen-Layer fuer Kamera-Parallax (PATCH Q: mit Einblend-Klasse)
                    const layerFar = document.createElement("div"); layerFar.className = "fx-depth fx-far fx-fading-in";
                    const layerNear = document.createElement("div"); layerNear.className = "fx-depth fx-near fx-fading-in";
                    host.appendChild(layerFar); host.appendChild(layerNear);
                    // naechsten Frame: Einblend-Klasse entfernen -> sanftes Fade-In
                    requestAnimationFrame(() => requestAnimationFrame(() => {
                        layerFar.classList.remove("fx-fading-in");
                        layerNear.classList.remove("fx-fading-in");
                    }));
                    // Thema-Konfiguration: type, anzahl, groesse[min,max], farben[], opacity[min,max]
                    const THEMES = {
                        buero:      { type:"dust",  n:64, sz:[2,4], col:["#fff8d6","#ffffff"], op:[.25,.6] },
                        flur:       { type:"dust",  n:82, sz:[2,5], col:["#ffffff","#dbe6ff"], op:[.3,.7] },
                        zentrale:   { type:"spark", n:62, sz:[2,4], col:["#bcdcff","#ffffff"], op:[.3,.7] },
                        serverraum: { type:"data",  n:95, sz:[2,4], col:["#7dffc8","#5ac8ff","#9affd5"], op:[.4,.85] },
                        kantine:    { type:"steam", n:48, sz:[6,14],col:["#fff2d2","#ffe8c0"], op:[.18,.4] },
                        lager:      { type:"dust",  n:70, sz:[2,5], col:["#dccdb4","#bfae90"], op:[.25,.55] },
                        konferenz:  { type:"spark", n:60, sz:[2,4], col:["#e1d7ff","#b9a9ff"], op:[.3,.65] },
                        boss_office:{ type:"spark", n:56, sz:[2,5], col:["#ff9a6a","#ffd2aa","#ff6a4a"], op:[.35,.8] },
                        archiv:     { type:"paper", n:66, sz:[3,6], col:["#ebe1c8","#d2c3a0","#c9b890"], op:[.3,.6] },
                        dach:       { type:"pollen",n:76, sz:[2,5], col:["#fffae6","#fff4c8","#ffffff"], op:[.35,.75] }
                    };
                    const baseCfg = THEMES[mapId] || THEMES.flur;
                    const cfg = Object.assign({}, baseCfg, { col: baseCfg.col });
                    if (lowParticleMode) cfg.n = Math.max(18, Math.floor(cfg.n * 0.38));
                    const W = host.clientWidth || 800, H = host.clientHeight || 520;
                    const rnd = (a,b) => a + Math.random()*(b-a);
                    const pick = arr => arr[Math.floor(Math.random()*arr.length)];
                    for (let i = 0; i < cfg.n; i++) {
                        const p = document.createElement("div");
                        p.className = "fxp " + cfg.type;
                        const size = rnd(cfg.sz[0], cfg.sz[1]);
                        const op = rnd(cfg.op[0], cfg.op[1]);
                        const col = pick(cfg.col);
                        p.style.width = size.toFixed(1) + "px";
                        p.style.height = (cfg.type === "data" ? size*rnd(3,6) : (cfg.type==="paper"? size*rnd(1.2,2):size)).toFixed(1) + "px";
                        p.style.left = rnd(0, W).toFixed(0) + "px";
                        p.style.top  = rnd(0, H).toFixed(0) + "px";
                        if (cfg.type === "spark" || cfg.type === "data" || cfg.type === "boss") p.style.color = col;
                        if (cfg.type === "data" || cfg.type === "paper") p.style.background = col;
                        else if (cfg.type === "spark") p.style.background = col;
                        else if (cfg.type === "dust") p.style.background = "radial-gradient(circle, " + col + ", transparent 70%)";
                        else if (cfg.type === "pollen") p.style.background = "radial-gradient(circle, " + col + ", transparent 72%)";
                        p.style.setProperty("--op", op.toFixed(2));
                        p.style.setProperty("--delay", (-rnd(0, 14)).toFixed(2) + "s");
                        p.style.setProperty("--dur", rnd(8, 20).toFixed(1) + "s");
                        p.style.setProperty("--tw", rnd(1.2, 3.2).toFixed(1) + "s");
                        p.style.setProperty("--dx", (rnd(-1,1)*rnd(20,90)).toFixed(0) + "px");
                        p.style.setProperty("--dy", (-rnd(15,70)).toFixed(0) + "px");
                        p.style.setProperty("--dy2", (rnd(20,80)).toFixed(0) + "px");
                        p.style.setProperty("--rise", (-rnd(90,180)).toFixed(0) + "px");
                        p.style.setProperty("--fall", rnd(180, 340).toFixed(0) + "px");
                        (Math.random() < 0.55 ? layerNear : layerFar).appendChild(p); // PATCH P: Tiefe
                    }
                    fxLayerNear = layerNear; fxLayerFar = layerFar; // PATCH P: fuer Kamera-Parallax cachen
                }
                window.BVSpawnMapParticles = spawnMapParticles;
                function spawnDoors() {
                    if (!doorLayer) return;
                    doorLayer.innerHTML = "";
                    for (const [doorId, door] of Object.entries(DOORS)) {
                        if (door.from !== currentMapId) continue;
                        const isBoss = door.label === "Chefbüro" || doorId.includes("boss");
                        const isLocked = door.requiresBossKey && !canAccessBoss();
                        const el = document.createElement("div");
                        el.className = "map-door map-door-iso" + (isBoss ? " boss" : "") + (isLocked ? " locked" : "") + (door.badEnding ? " bad-exit" : "");
                        // PATCH F: eingelassene Iso-Tuer (SVG) statt CSS-Box, folgt Map-Rotation
                        const isoD = isoDoorSvg(door.fromX, door.fromY, { boss: isBoss, locked: isLocked, bad: !!door.badEnding, double: !!door.double });
                        if (isoD) {
                            el.style.position = "absolute";
                            const baseD = BV3D.project(door.fromX, door.fromY, 0);
                            el.style.left = (baseD.x + isoD.ax) + "px";
                            el.style.top = (baseD.y + isoD.ay) + "px";
                            // Tuer muss ueber dem Occluder der eigenen Wand liegen (occluder=base+90+22=base+112; door=base+45) -> Offset 75
                            el.style.zIndex = getMapDepth(door.fromX, door.fromY, "door") + 75;
                            el.innerHTML = isoD.svg + `<div class="door-label">${door.label || ""}</div>` + (isLocked ? '<div class="door-lock-badge">🔒</div>' : "");
                        } else {
                            el.innerHTML = `<div class="door-3d-shadow"></div><div class="door-frame"><div class="door-3d-frame"></div><div class="door-3d-side"></div><div class="door-3d-panel"><div class="door-3d-knob"></div></div></div><div class="door-icon">🚪</div>`;
                            placeMapElement(el, door.fromX, door.fromY, "door");
                        }
                        el.style.pointerEvents = "none";
                        el.dataset.doorId = doorId;
                        doorLayer.appendChild(el);
                    }
                    parseEmojis(doorLayer);
                }


                function canAccessBoss() {
                    // Count total enemies that need to be defeated across all maps
                    let totalEnemies = 0;
                    let defeatedCount = 0;
                    
                    // Check all maps for enemies
                    const mapsToCheck = ["flur", "buero", "zentrale", "kantine", "lager", "konferenz", "serverraum"];
                    
                    mapsToCheck.forEach(mapId => {
                        const mapData = MAPS[mapId];
                        if (mapData && mapData.npcs) {
                            const enemies = mapData.npcs.filter(n => n.type === "enemy" && !n.isBoss);
                            enemies.forEach(npc => {
                                totalEnemies++;
                                const key = `${mapId}_${npc.x}_${npc.y}_${npc.enemyId}`;
                                if (defeatedEnemies.has(key)) {
                                    defeatedCount++;
                                }
                            });
                        }
                    });
                    
                    // Require at least 10 enemies defeated to enter boss room
                    const minRequired = Math.min(10, totalEnemies);
                    return defeatedCount >= minRequired;
                }

                function openBadEndingWarning(doorId) {
                    if (isTransitioning) return;
                    window.showChoice("⚠️ WARNUNG: Wenn du das Gebäude jetzt verlässt, gilt das als Arbeitsverweigerung. Du wirst gekündigt. Willst du wirklich rausgehen?", [
                        { label: "Nein, ich bleibe", value: "no", hint: "↩" },
                        { label: "Ja, ich will gehen", value: "yes", hint: "🚪" }
                    ], "Sicherheits-System", "⚠️", (val) => {
                        if (val !== "yes") {
                            showMessage("Gute Entscheidung. Zurück an die Arbeit.", "Sicherheits-System", "✅");
                            return;
                        }
                        window.showChoice("LETZTE WARNUNG: Sobald du diese Tür öffnest, ist dein Arbeitsvertrag beendet. Trotzdem gehen?", [
                            { label: "Abbrechen", value: "cancel", hint: "🛑" },
                            { label: "Trotzdem gehen", value: "leave", hint: "📄" }
                        ], "Personalabteilung", "📋", (confirmVal) => {
                            if (confirmVal === "leave") triggerBadEnding(doorId);
                            else showMessage("Die Tür bleibt geschlossen. Noch ist nichts passiert.", "Personalabteilung", "📋");
                        });
                    });
                }

                function triggerBadEnding(doorId) {
                    isTransitioning = true;
                    gameState = "TRANSITION";
                    keysHeld = {};
                    stopMoveLoop();
                    if (interactionHint) interactionHint.classList.remove("visible");
                    if (msgBox) hideMsgBox(true);
                    const doorEl = doorLayer?.querySelector(`[data-door-id="${doorId}"]`);
                    if (doorEl) doorEl.classList.add("door-opening");
                    const flash = document.createElement("div");
                    flash.className = "map-teleport-flash-v420 bad-ending-flash";
                    document.getElementById("rpg-game-screen")?.appendChild(flash);
                    setTimeout(() => {
                        if (doorEl) doorEl.classList.remove("door-opening");
                        if (flash.parentElement) flash.remove();
                        showBadEndingScreen();
                    }, 950);
                }

                function showBadEndingScreen() {
                    const update = (id, val) => { const el = document.getElementById(id); if (el) el.innerText = val; };
                    update("bad-ending-name", player.name || "Held");
                    update("bad-ending-level", player.lvl || 1);
                    update("bad-ending-gold", player.gold || 0);
                    update("bad-ending-battles", battleCount || 0);
                    update("bad-ending-chests", chestCount || 0);
                    showScreen("rpg-bad-ending-screen");
                    gameState = "BAD_ENDING";
                    isTransitioning = false;
                    const screen = document.getElementById("rpg-bad-ending-screen");
                    parseEmojis(screen);
                    spawnBadEndingPapers();
                }

                function spawnBadEndingPapers() {
                    const screen = document.getElementById("rpg-bad-ending-screen");
                    if (!screen) return;
                    screen.querySelectorAll('.bad-ending-paper').forEach(p => p.remove());
                    for (let i = 0; i < 18; i++) {
                        const paper = document.createElement('div');
                        paper.className = 'bad-ending-paper';
                        paper.style.left = (Math.random() * 100) + '%';
                        paper.style.animationDuration = (2.8 + Math.random() * 2.2).toFixed(2) + 's';
                        paper.style.animationDelay = (Math.random() * 1.2).toFixed(2) + 's';
                        paper.style.transform = `rotate(${Math.random()*80-40}deg)`;
                        screen.appendChild(paper);
                    }
                }

                function handleDoor(x, y, tileData) {
                    if (isTransitioning) return;

                    for (const [doorId, door] of Object.entries(DOORS)) {
                        const hitsExtra = Array.isArray(door.extraTiles) && door.extraTiles.some(t => t[0] === x && t[1] === y);
                        if (door.from === currentMapId && ((door.fromX === x && door.fromY === y) || hitsExtra)) {
                            if (door.badEnding) { openBadEndingWarning(doorId); return; }
                            if (door.requiresBossKey && !canAccessBoss()) {
                                const remaining = (MAPS.flur?.npcs?.filter(n => {
                                    if (n.type !== "enemy" || n.isBoss) return false;
                                    const key = `flur_${n.x}_${n.y}_${n.enemyId}`;
                                    return !defeatedEnemies.has(key);
                                }) || []).length;
                                showMessage(`Die Tür ist verschlossen! Besiege noch ${remaining} Gegner.`, "🚪 Tür", "🚪");
                                return;
                            }

                            // 2.5D Door animation + safer teleport position.
                            // Während der Türanimation ist Bewegung komplett gesperrt.
                            closeMessageForInterrupt("TRANSITION");
                            isTransitioning = true;
                            gameState = "TRANSITION";
                            keysHeld = {};
                            stopMoveLoop();
                            if (interactionHint) interactionHint.classList.remove("visible");
                            const doorEl = doorLayer?.querySelector(`[data-door-id="${doorId}"]`);
                            if (doorEl) doorEl.classList.add("door-opening");
                            pendingLoadPos = { mapId: door.to, x: door.toX, y: door.toY, facing: player.facing || "down" };
                            setTimeout(() => { if (doorEl) doorEl.classList.remove("door-opening"); }, 620);
                            setTimeout(() => {
                                isTransitioning = false;
                                loadMap(door.to, true);
                                setTimeout(() => {
                                    const targetDoor = Object.entries(DOORS).find(([id, d]) => d.from === door.to && d.to === door.from);
                                    if (targetDoor && doorLayer) {
                                        const targetEl = doorLayer.querySelector(`[data-door-id="${targetDoor[0]}"]`);
                                        if (targetEl) {
                                            targetEl.classList.add("door-closing");
                                            setTimeout(() => targetEl.classList.remove("door-closing"), 560);
                                        }
                                    }
                                }, 620);
                            }, doorEl ? 260 : 0);
                            return;
                        }
                    }
                }

                function checkLevelUp() {
                    const oldLvl = player.lvl;
                    while (player.exp >= player.expNext) {
                        player.lvl++;
                        player.exp -= player.expNext;
                        player.expNext = Math.floor(player.expNext * 1.4);
                        player.maxHp += 20;
                        player.hp = player.maxHp;
                        player.atk += 4;
                        player.def += 2;
                        player.maxMp += 3;
                        player.mp = player.maxMp;
                    }
                    const gained = player.lvl - oldLvl;
                    if (gained > 0) {
                        window._pendingLevelUpCount = gained;
                        setTimeout(function () {
                            if (typeof window.offerLevelUpChoice === 'function') window.offerLevelUpChoice();
                        }, 600);
                    }
                }

                // ===== MINIMAP =====
                window.toggleMinimap = function () {
                    minimapVisible = !minimapVisible;
                    const container = document.getElementById("minimap-container");
                    if (container) container.classList.toggle("visible", minimapVisible);
                    if (minimapVisible) updateMinimap();
                };

                // BUGFIX: Throttled Minimap Update - verhindert Lag bei schnellen Bewegungen
                let minimapUpdateQueued = false;
                const MINIMAP_UPDATE_INTERVAL = 150; // Max alle 150ms updaten (Performance)

                function queueMinimapUpdate() {
                    if (!minimapVisible) return;
                    if (minimapUpdateQueued) return; // Bereits ein Update geplant
                    
                    minimapUpdateQueued = true;
                    setTimeout(() => {
                        minimapUpdateQueued = false;
                        updateMinimap();
                    }, MINIMAP_UPDATE_INTERVAL);
                }

                function updateMinimap() {
                    if (!minimapVisible) return;

                    const miniCanvas = document.getElementById("minimap-canvas");
                    if (!miniCanvas) return;
                    const mctx = miniCanvas.getContext("2d");

                    // ARENA PATCH: SECRET ROOM HIDE MINIMAP
                    if (currentMapId === "secret_room") {
                        miniCanvas.width = 150;
                        miniCanvas.height = 100;
                        mctx.fillStyle = "#05070d";
                        mctx.fillRect(0, 0, miniCanvas.width, miniCanvas.height);
                        mctx.fillStyle = "#ff6b6b";
                        mctx.font = "12px monospace";
                        mctx.fillText("SIGNAL", 49, 42);
                        mctx.fillText("BLOCKIERT", 36, 60);
                        return;
                    }

                    const mapCols = currentMap[0]?.length || 27;
                    const mapRows = currentMap.length || 17;
                    const scale = Math.min(150 / mapCols, 100 / mapRows);

                    miniCanvas.width = mapCols * scale;
                    miniCanvas.height = mapRows * scale;

                    for (let y = 0; y < mapRows; y++) {
                        for (let x = 0; x < mapCols; x++) {
                            const tile = currentMap[y] ? currentMap[y][x] : 0;
                            const tileData = TILES[tile] || TILES[0];
                            mctx.fillStyle = tileData.block ? "#333" : "#666";
                            if (tileData.name?.includes("door")) mctx.fillStyle = "#cc0";
                            mctx.fillRect(x * scale, y * scale, scale, scale);
                        }
                    }

                    npcs.forEach(npc => {
                        if (npc.type === "enemy") mctx.fillStyle = "#f44";
                        else if (npc.type === "shop") mctx.fillStyle = "#fc0";
                        else mctx.fillStyle = "#4af";
                        mctx.fillRect(npc.x * scale, npc.y * scale, scale, scale);
                    });

                    currentChests.forEach(chest => {
                        if (!chest.opened) {
                            mctx.fillStyle = chest.type === "rare" ? "#f0f" : "#fa0";
                            mctx.fillRect(chest.x * scale, chest.y * scale, scale, scale);
                        }
                    });

                    mctx.fillStyle = "#0f0";
                    mctx.fillRect(player.x * scale - 1, player.y * scale - 1, scale + 2, scale + 2);
                }

                // ===== CHEAT SYSTEM =====
                window.toggleCheatConsole = function () {
                    if (gameState === "EDITOR" || document.getElementById("rpg-battle-editor-screen")?.classList.contains("active")) {
                        const consoleEl = document.getElementById("cheat-console");
                        cheatConsoleVisible = false;
                        if (consoleEl) consoleEl.classList.remove("visible");
                        return;
                    }
                    const consoleEl = document.getElementById("cheat-console");
                    cheatConsoleVisible = !cheatConsoleVisible;
                    if (consoleEl) consoleEl.classList.toggle("visible", cheatConsoleVisible);
                    if (cheatConsoleVisible) {
                        const input = document.getElementById("cheat-input");
                        if (input) {
                            input.value = ""; // Clear input to prevent 'C' from appearing
                            setTimeout(() => input.focus(), 10);
                        }
                    }
                };

                function logCheat(msg, type = "info") {
                    const log = document.getElementById("cheat-log");
                    if (!log) return;
                    const line = document.createElement("div");
                    line.className = type;
                    line.innerText = "> " + msg;
                    log.appendChild(line);
                    log.scrollTop = log.scrollHeight;
                }

                function executeCheat(cmd) {
                    const parts = cmd.trim().toLowerCase().split(" ");
                    const cheat = parts[0];
                    const arg = parseInt(parts[1]) || 0;

                    switch (cheat) {
                        case "/help":
                            logCheat("Befehle: /gold, /hp, /maxhp, /mp, /atk, /def, /lvl, /exp, /tp, /godmode, /items, /killall, /openall, /heal, /skills, /ending, /reset", "info");
                            break;
                        case "/gold":
                        case "/money":
                            player.gold += arg || 1000;
                            updateHUD();
                            logCheat(`+${arg || 1000} Gold!`, "success");
                            break;
                        case "/hp":
                            player.hp = Math.min(player.maxHp, player.hp + (arg || player.maxHp));
                            updateHUD();
                            logCheat(`HP geheilt!`, "success");
                            break;
                        case "/maxhp":
                            player.maxHp += arg || 100;
                            player.hp = player.maxHp;
                            updateHUD();
                            logCheat(`Max HP +${arg || 100}!`, "success");
                            break;
                        case "/mp":
                            player.mp = Math.min(player.maxMp, player.mp + (arg || player.maxMp));
                            updateHUD();
                            logCheat(`MP aufgefüllt!`, "success");
                            break;
                        case "/atk":
                            player.atk += arg || 50;
                            updateHUD();
                            logCheat(`Angriff +${arg || 50}!`, "success");
                            break;
                        case "/def":
                            player.def += arg || 20;
                            updateHUD();
                            logCheat(`Verteidigung +${arg || 20}!`, "success");
                            break;
                        case "/lvl":
                            const lvl = arg || 10;
                            player.lvl = lvl;
                            player.maxHp = 100 + (lvl - 1) * 20;
                            player.hp = player.maxHp;
                            player.atk = 10 + (lvl - 1) * 4;
                            player.def = 2 + (lvl - 1) * 2;
                            player.maxMp = 10 + (lvl - 1) * 3;
                            player.mp = player.maxMp;
                            updateHUD();
                            logCheat(`Level ${lvl}!`, "success");
                            break;
                        case "/exp":
                            player.exp += arg || 100;
                            checkLevelUp();
                            updateHUD();
                            logCheat(`+${arg || 100} EXP!`, "success");
                            break;
                        case "/tp":
                            const mapName = parts[1] || "buero";
                            if (MAPS[mapName]) {
                                loadMap(mapName, true);
                                logCheat(`Teleportiert zu: ${MAPS[mapName].name}`, "success");
                            } else {
                                logCheat(`Map nicht gefunden. Verfügbar: ${Object.keys(MAPS).join(", ")}`, "error");
                            }
                            break;
                        case "/godmode":
                            godMode = !godMode;
                            logCheat(`God Mode: ${godMode ? "AN" : "AUS"}`, godMode ? "success" : "info");
                            break;
                        case "/items":
                            SHOP_ITEMS.forEach(item => {
                                if (item.heal || item.mpHeal) {
                                    const existing = player.inventory.find(i => i.id === item.id);
                                    if (existing) existing.count += 10;
                                    else player.inventory.push({ id: item.id, name: item.icon + " " + item.name, heal: item.heal, mpHeal: item.mpHeal || 0, count: 10 });
                                }
                            });
                            logCheat("Alle Items erhalten!", "success");
                            break;
                        case "/killall":
                            let killedCount = 0;
                            // Alle Maps durchgehen und alle Enemies besiegen (außer Boss)
                            Object.keys(MAPS).forEach(mapId => {
                                const mapData = MAPS[mapId];
                                if (mapData.npcs) {
                                    mapData.npcs.forEach(npc => {
                                        // Nur normale Enemies, keine Bosse
                                        if (npc.type === "enemy" && !npc.isBoss) {
                                            const enemyKey = `${mapId}_${npc.x}_${npc.y}_${npc.enemyId || 'enemy'}`;
                                            if (!defeatedEnemies.has(enemyKey)) {
                                                defeatedEnemies.add(enemyKey);
                                                killedCount++;
                                            }
                                        }
                                    });
                                }
                            });
                            // Aktuelle Map NPCs entfernen (außer Boss)
                            npcs = npcs.filter(n => n.type !== "enemy" || n.isBoss);
                            spawnNPCs();
                            logCheat(`Alle Gegner besiegt! (${killedCount} Gegner, Boss ausgenommen)`, "success");
                            break;
                        case "/openall":
                            let openedCount = 0;
                            let totalGold = 0;
                            // Alle Maps durchgehen und alle Kisten öffnen
                            Object.keys(MAPS).forEach(mapId => {
                                const mapData = MAPS[mapId];
                                if (mapData.chests) {
                                    mapData.chests.forEach(chest => {
                                        const chestKey = `${mapId}_${chest.x}_${chest.y}`;
                                        if (!openedChests.has(chestKey)) {
                                            openedChests.add(chestKey);
                                            openedCount++;
                                            // Gold basierend auf Kisten-Typ
                                            if (chest.type === "rare") {
                                                totalGold += 75;
                                            } else {
                                                totalGold += 25;
                                            }
                                        }
                                    });
                                }
                            });
                            // Aktuelle Map Kisten aktualisieren
                            currentChests.forEach(chest => {
                                chest.opened = true;
                            });
                            spawnChests();
                            player.gold += totalGold;
                            updateHUD();
                            logCheat(`Alle Kisten in allen Maps geöffnet! (${openedCount} Kisten, +${totalGold} Gold)`, "success");
                            break;
                        case "/heal":
                            player.hp = player.maxHp;
                            player.mp = player.maxMp;
                            updateHUD();
                            logCheat("Vollständig geheilt! HP & MP aufgefüllt!", "success");
                            break;
                        case "/skills":
                        case "/skill":
                            if (!player.unlockedSkills) player.unlockedSkills = [];
                            const allSkillIds = ["tacker", "kaffee", "meeting", "papier", "fax", "printer", "ueberstunden"];
                            let addedCount = 0;
                            allSkillIds.forEach(skillId => {
                                if (!player.unlockedSkills.includes(skillId)) {
                                    player.unlockedSkills.push(skillId);
                                    addedCount++;
                                }
                            });
                            logCheat(`Alle Skills freigeschaltet! (+${addedCount} neue Skills)`, "success");
                            break;
                        case "/ending":
                        case "/end":
                            logCheat("Ending wird geladen...", "info");
                            toggleCheatConsole();
                            setTimeout(() => { showEnding(); }, 300);
                            break;
                        case "/reset":
                            logCheat("Spiel wird zurückgesetzt...", "info");
                            setTimeout(() => { resetGame(); showScreen("rpg-name-screen"); gameState = "NAME"; }, 500);
                            break;
                        case "/mapdebug":
                            toggleMapDebug();
                            break;
                        case "/mapvalidate":
                            validateAllMaps();
                            logCheat("Map-Validator in Konsole ausgegeben.", "info");
                            break;
                        case "/mapquality":
                            toggleMapQuality();
                            break;
                        default:
                            logCheat(`Unbekannt: ${cheat}. Tippe /help`, "error");
                    }
                }

                const cheatInput = document.getElementById("cheat-input");
                if (cheatInput) {
                    cheatInput.addEventListener("keydown", (e) => {
                        if (e.key === "Enter") {
                            const cmd = e.target.value.trim();
                            if (cmd) { executeCheat(cmd); e.target.value = ""; }
                        }
                        if (e.key === "Escape") toggleCheatConsole();
                        e.stopPropagation();
                    });
                }

                // ===== RESET FUNCTION =====
                function resetGame() {
                    // BUGFIX: Laufende Cutscene sauber beenden falls aktiv
                    if (typeof window.BVForceEndCutscene === 'function') {
                        window.BVForceEndCutscene('reset');
                    }
                    stopCameraLoop();
                    stopNPCMovementLoop();
                    // Clear ALL game-session intervals/timeouts
                    clearAllGameIntervals();

                    // Erfolge beim Neustart zurücksetzen
                    try { localStorage.removeItem('bv_achievements'); } catch (e) {}
                    if (typeof window.resetAchievementCache === 'function') window.resetAchievementCache();

                    // Hide quit modal if visible
                    const quitModal = document.getElementById('quit-modal');
                    if (quitModal) quitModal.style.display = 'none';

                    gameState = "SPLASH";
                    player = {
                        name: "Held", x: 5, y: 7, hp: 100, maxHp: 100, mp: 10, maxMp: 10,
                        gold: 50, lvl: 1, atk: 10, def: 2, exp: 0, expNext: 30,
                        inventory: [{ id: "kaffee", name: "☕ Kaffee", heal: 40, count: 3 }],
                        gender: "m", dept: "einkauf", sprite: "🧑‍💼", facing: "right",
                        moveSpeed: 1, invisible: false,
                        unlockedSkills: ["tacker", "kaffee", "meeting"]
                    };
                    // BUGFIX: Shop/Skillshop-Patches arbeiten über window.player.
                    // Nach einer Neu-Zuweisung muss die globale Referenz wieder auf das echte Spielerobjekt zeigen.
                    window.player = player;
                    playerGender = "m"; playerDept = "einkauf";
                    currentMapId = ""; currentMap = []; npcs = []; currentDecos = []; currentChests = [];
                    currentEnemy = null; msgQueue = []; isTyping = false; msgLocked = false;
                    fullText = ""; typeIndex = 0; // Reset TypeWrite state
                    if (typeTimer) clearTimeout(typeTimer);
                    
                    // BUGFIX: Alle Contract-TypeWrite-Timeouts abbrechen
                    contractTypeTimeouts.forEach(id => clearTimeout(id));
                    contractTypeTimeouts = [];
                    
                    battleLocked = false; defeatedEnemies = new Set(); openedChests = new Set();
                    metNPCs = []; battleCount = 0; chestCount = 0; bossPhase = 0; hasLostToBoss = false;
                    _hudGoldCurrent = 0; if (_hudGoldAnim) { cancelAnimationFrame(_hudGoldAnim); _hudGoldAnim = null; }
                    nearbyNPC = null; nearbyChest = null; isTransitioning = false; isBattleStarting = false;
                    isMoving = false; godMode = false; minimapVisible = false; cheatConsoleVisible = false;

                    // Reset emails to original state
                    if (typeof resetEmails === 'function') resetEmails();

                    if (transitionTimeout) clearTimeout(transitionTimeout);
                    if (battleStartTimeout) clearTimeout(battleStartTimeout);
                    if (turnIndicatorTimeout) clearTimeout(turnIndicatorTimeout);
                    if (vsFadeOutTimeout) { clearTimeout(vsFadeOutTimeout); vsFadeOutTimeout = null; }

                    // Reset UI
                    if (typeof resetQuizScene === "function") resetQuizScene();
                    if (msgBox) hideMsgBox(true);
                    if (interactionHint) interactionHint.classList.remove("visible");
                    document.getElementById("victory-screen")?.classList.remove("visible");
                    document.getElementById("defeat-screen")?.classList.remove("visible");
                    document.getElementById("battle-item-menu")?.classList.remove("visible");
                    document.getElementById("battle-skill-menu")?.classList.remove("visible");
                    document.getElementById("battle-vs-splash")?.classList.remove("active", "vs-fade-out");
                    document.getElementById("turn-indicator")?.classList.remove("active", "enemy-turn");
                    document.getElementById("levelup-display")?.classList.remove("visible");
                    document.getElementById("battle-transition-in")?.classList.remove("active");
                    document.getElementById("battle-panels")?.classList.remove("active", "open", "close");
                    // Reset effects (PATCH S: auch neue fx-* Klassen + Partikel-Container leeren)
                    const _gw = document.getElementById("rpg-game-window");
                    if (_gw) _gw.classList.remove("effect-particles", "effect-dim", "effect-windows",
                        "fx-buero","fx-flur","fx-zentrale","fx-serverraum","fx-kantine",
                        "fx-lager","fx-konferenz","fx-boss","fx-archiv","fx-dach");
                    const _fxp = document.getElementById("rpg-fx-particles");
                    if (_fxp) _fxp.innerHTML = "";
                    if (typeof fxLayerNear !== "undefined") { fxLayerNear = null; fxLayerFar = null; }
                    document.getElementById("battle-transition-out")?.classList.remove("active");
                    document.getElementById("cheat-console")?.classList.remove("visible");
                    document.getElementById("minimap-container")?.classList.remove("visible");

                    const nameErr = document.getElementById("name-error");
                    const nameInp = document.getElementById("rpg-name-input");
                    const msgText = document.getElementById("msg-text");
                    const cheatLog = document.getElementById("cheat-log");
                    if (nameErr) nameErr.innerText = "";
                    if (nameInp) nameInp.value = "";
                    if (msgText) msgText.innerHTML = "";
                    if (cheatLog) cheatLog.innerHTML = "";
                    if (mapTrans) mapTrans.classList.remove("active", "battle-hold", "no-content", "opening");

                    // Clear signature and badge previews
                    document.querySelectorAll('.signature-x').forEach(el => el.innerText = '');
                    const previewNameEl = document.getElementById('preview-name');
                    const badgeRoleEl = document.getElementById('badge-role');
                    const badgeDeptEl = document.getElementById('badge-dept');
                    if (previewNameEl) previewNameEl.innerText = 'HELD';
                    if (badgeRoleEl) { badgeRoleEl.innerText = GENDER_TITLES['m']; badgeRoleEl.style.display = 'none'; }
                    if (badgeDeptEl) { badgeDeptEl.innerText = 'Abteilung: Einkauf'; badgeDeptEl.style.display = 'none'; }

                    // Re-enable contract button and all name-input controls
                    const contractBtn = document.getElementById("rpg-start-btn");
                    if (contractBtn) { contractBtn.disabled = false; contractBtn.style.opacity = "1"; }
                    if (nameInp) nameInp.disabled = false;
                    document.querySelectorAll(".gender-btn").forEach(btn => btn.disabled = false);
                    document.querySelectorAll(".dept-btn").forEach(btn => btn.disabled = false);

                    cameraX = 0; cameraY = 0; targetCameraX = 0; targetCameraY = 0;
                    if (cameraEl) cameraEl.style.transform = "";

                    // Reset Computer OS Startup
                    window.computerStartupShown = false;
                    const computerScreen = document.getElementById("rpg-computer-screen");
                    if (computerScreen) {
                        computerScreen.classList.remove("active");
                        // Clear any startup overlays
                        const startup = document.getElementById("computer-startup");
                        if (startup) startup.remove();
                    }
                    // Close all computer windows
                    if (typeof closeAllWindows === "function") closeAllWindows();
                    // Reset HUD display
                    const rpgHud = document.getElementById("rpg-hud");
                    if (rpgHud) rpgHud.style.display = "";

                    // Reset Easter Event State
                    easterEventState = {
                        active: false,
                        completed: false,
                        collectedEggs: [],
                        totalEggs: 10
                    };
                    currentEasterEggs = [];
                    const easterUI = document.getElementById("easter-event-ui");
                    if (easterUI) {
                        easterUI.style.display = "none";
                        easterUI.classList.remove("complete");
                    }

                    showScreen(null);

                    // Ensure title settings modal is closed and cleaned up
                    const _tsm = document.getElementById('title-settings-modal');
                    if (_tsm) { _tsm.classList.remove('active', 'closing'); }
                    const _ecm = document.getElementById('exit-confirm-modal');
                    if (_ecm) { _ecm.classList.remove('active', 'closing'); }
                }

                // ===== SAVEFILE SYSTEM =====
                window.SAVEFILE_KEY = "bueroversum_save";

                function getSaveFile() {
                    const save = localStorage.getItem(window.SAVEFILE_KEY);
                    return save ? JSON.parse(save) : null;
                }

                function setSaveFile(data) {
                    localStorage.setItem(window.SAVEFILE_KEY, JSON.stringify(data));
                }

                function deleteSaveFile() {
                    localStorage.removeItem(window.SAVEFILE_KEY);
                    try { localStorage.removeItem('bv_achievements'); } catch (e) {}
                    if (typeof window.resetAchievementCache === 'function') window.resetAchievementCache();
                }

                function hasSaveFile() {
                    return getSaveFile() !== null;
                }

                // ===== RESET BATTLE STATE =====
                function resetBattleState() {
                    // Stop any ongoing battle animations
                    const battleScreen = document.getElementById("rpg-battle-screen");
                    if (battleScreen) {
                        battleScreen.classList.remove("active");
                        battleScreen.style.animation = "";
                        battleScreen.style.display = "";
                    }

                    // Reset battle transition animations
                    const battleTransIn = document.getElementById("battle-transition-in");
                    const battleTransOut = document.getElementById("battle-transition-out");
                    if (battleTransIn) {
                        battleTransIn.classList.remove("active");
                        battleTransIn.style.animation = "";
                        // Reset all stripes inside
                        battleTransIn.querySelectorAll(".bt-stripe").forEach(stripe => {
                            stripe.style.animation = "";
                        });
                    }
                    if (battleTransOut) {
                        battleTransOut.classList.remove("active");
                        battleTransOut.style.animation = "";
                        battleTransOut.querySelectorAll(".bt-out-top, .bt-out-bottom").forEach(el => {
                            el.style.animation = "";
                        });
                    }

                    // Reset battle panels - this is often the culprit!
                    const battlePanels = document.getElementById("battle-panels");
                    if (battlePanels) {
                        battlePanels.classList.remove("active", "open", "close");
                        battlePanels.style.animation = "";
                        battlePanels.style.display = "";
                        // Remove inline styles that might have been added
                        const panels = battlePanels.querySelectorAll(".battle-panel");
                        panels.forEach(panel => {
                            // Stop animation immediately
                            panel.style.animation = "none";
                            // Reset to default positions (top panel goes back to -55%, bottom to bottom: -55%)
                            if (panel.classList.contains("top")) {
                                panel.style.top = "-55%";
                            } else if (panel.classList.contains("bottom")) {
                                panel.style.bottom = "-55%";
                            }
                            panel.style.transform = "";
                            // Force reflow
                            void panel.offsetWidth;
                            // Clear inline styles so CSS can take over
                            panel.style.animation = "";
                            panel.style.top = "";
                            panel.style.bottom = "";
                            panel.style.transform = "";
                        });
                    }

                    // Reset VS splash
                    if (vsFadeOutTimeout) { clearTimeout(vsFadeOutTimeout); vsFadeOutTimeout = null; }
                    const vsSplash = document.getElementById("battle-vs-splash");
                    if (vsSplash) {
                        vsSplash.classList.remove("active", "vs-fade-out");
                        vsSplash.style.animation = "";
                        vsSplash.style.animationDuration = "";
                    }

                    // Reset turn indicator
                    const turnIndicator = document.getElementById("turn-indicator");
                    if (turnIndicator) {
                        turnIndicator.classList.remove("active", "enemy-turn");
                    }

                    // Reset victory/defeat screens
                    const victoryScreen = document.getElementById("victory-screen");
                    const defeatScreen = document.getElementById("defeat-screen");
                    if (victoryScreen) {
                        victoryScreen.classList.remove("visible", "active");
                        victoryScreen.style.animation = "";
                    }
                    if (defeatScreen) {
                        defeatScreen.classList.remove("visible", "active");
                        defeatScreen.style.animation = "";
                    }

                    // Reset battle submenus
                    document.getElementById("battle-item-menu")?.classList.remove("visible");
                    document.getElementById("battle-skill-menu")?.classList.remove("visible");

                    // Reset level up display
                    document.getElementById("levelup-display")?.classList.remove("visible");

                    // Clear any enemy damage displays
                    const dmgEnemy = document.getElementById("battle-dmg-enemy");
                    const dmgPlayer = document.getElementById("battle-dmg-player");
                    if (dmgEnemy) dmgEnemy.innerHTML = "";
                    if (dmgPlayer) dmgPlayer.innerHTML = "";

                    // Reset effect layers
                    const effectEnemy = document.getElementById("battle-effect-enemy");
                    const effectPlayer = document.getElementById("battle-effect-player");
                    if (effectEnemy) effectEnemy.className = "";
                    if (effectPlayer) effectPlayer.className = "";

                    // Reset enemy sprite animation
                    const enemySprite = document.getElementById("battle-enemy-sprite");
                    if (enemySprite) {
                        enemySprite.style.animation = "";
                        enemySprite.style.transform = "";
                        enemySprite.style.opacity = "";
                    }

                    // Reset player sprite animation
                    const playerSprite = document.getElementById("battle-player-sprite");
                    if (playerSprite) {
                        playerSprite.style.animation = "";
                        playerSprite.style.transform = "";
                    }

                    // Reset game window effects - IMPORTANT: Clear shake animations!
                    const gameWindow = document.getElementById("rpg-game-window");
                    if (gameWindow) {
                        // Remove effect classes
                        gameWindow.classList.remove("effect-particles", "effect-dim", "effect-windows", "screen-shake");
                        // Clear inline animation style (from battleShake, battleShakeHeavy, etc.)
                        gameWindow.style.animation = "";
                        // Clear any transform from shake effects
                        gameWindow.style.transform = "";
                        // Clear any opacity/transition overrides
                        gameWindow.style.opacity = "";
                        gameWindow.style.transition = "";
                        // Force reflow to apply changes
                        void gameWindow.offsetWidth;
                    }

                    // Reset Boss effects and fire particles
                    const enemyHudInner = document.querySelector(".enemy-hud-inner");
                    const battleEnemyArea = document.getElementById("battle-enemy-area");
                    const battleParticles = document.querySelector(".battle-particles");
                    const battleEnemyHud = document.getElementById("battle-enemy-hud");
                    if (battleEnemyHud) battleEnemyHud.classList.remove("enemy-hud-defeated");
                    if (enemyHudInner) enemyHudInner.classList.remove("is-boss");
                    if (battleEnemyArea) battleEnemyArea.classList.remove("is-boss-battle", "has-fire");
                    // Remove all boss effect layers
                    if (battleParticles) {
                        const dustLayer3 = battleParticles.querySelector(".dust-layer-3");
                        const glowLayer = battleParticles.querySelector(".dust-layer-glow");
                        const fireParticles = battleParticles.querySelector(".fire-particles");
                        if (dustLayer3) dustLayer3.remove();
                        if (glowLayer) glowLayer.remove();
                        if (fireParticles) fireParticles.remove();
                    }

                    // Reset battle state variables
                    isBattleStarting = false;
                    battleLocked = false;
                    currentEnemy = null;
                }

                // ===== OPEN/CLOSE RPG =====
                window.openRPG = function () {
                    // Cancel any stale closeRPG timeout (race condition fix)
                    if (_closeRPGTimeoutId) { clearTimeout(_closeRPGTimeoutId); _closeRPGTimeoutId = null; }
                    // Cancel any previous openRPG timeouts (re-entry guard)
                    if (_openRPGTimeout1) { clearTimeout(_openRPGTimeout1); _openRPGTimeout1 = null; }
                    if (_openRPGTimeout2) { clearTimeout(_openRPGTimeout2); _openRPGTimeout2 = null; }
                    // Clear ALL game-session intervals/timeouts from any previous session
                    clearAllGameIntervals();

                    // Reset everything including battle state
                    resetBattleState();
                    resetGame();

                    // Remove all old overlay classes first
                    overlay.classList.remove("open", "opening", "closing");

                    // Force reflow to reset any CSS transitions
                    void overlay.offsetWidth;

                    // Reset game window completely - clear any battle shake animations
                    const gameWindow = document.getElementById("rpg-game-window");
                    if (gameWindow) {
                        // CRITICAL: Clear any inline animation from battle shake
                        gameWindow.classList.remove("gw-zoom-in");
                        gameWindow.style.animation = "none";
                        gameWindow.style.transition = "none";
                        gameWindow.style.opacity = "0";
                        gameWindow.style.transform = "scale(0.7) translateY(80px)";
                        // Force reflow to apply all changes immediately
                        void gameWindow.offsetWidth;
                        // CRITICAL: Clear inline styles so CSS rules can take over
                        // Without this, inline styles override the CSS :)
                        gameWindow.style.animation = "";
                        gameWindow.style.transition = "";
                        gameWindow.style.opacity = "";
                        gameWindow.style.transform = "";
                    }

                    overlay.classList.add("opening");
                    document.body.classList.add("rpg-active");
                    if (splash) splash.classList.add("active");
                    gameState = "SPLASH";
                    splashLoaded = false;
                    // Reset and start the splash loader + canvas
                    resetSplashLoader();
                    stopTitleCanvas();
                    stopSplashCanvas();
                    _openRPGTimeout1 = setTimeout(() => {
                        _openRPGTimeout1 = null;
                        initSplashLoader();
                        initSplashCanvas();
                    }, 100);
                    _openRPGTimeout2 = setTimeout(() => {
                        _openRPGTimeout2 = null;
                        overlay.classList.remove("opening");
                        overlay.classList.add("open");
                        parseEmojis(overlay);
                    }, 50);
                };

                window.closeRPG = function () {
                    // Cancel any stale openRPG timeouts (race condition fix)
                    if (_openRPGTimeout1) { clearTimeout(_openRPGTimeout1); _openRPGTimeout1 = null; }
                    if (_openRPGTimeout2) { clearTimeout(_openRPGTimeout2); _openRPGTimeout2 = null; }
                    // Cancel any previous closeRPG timeout (re-entry guard)
                    if (_closeRPGTimeoutId) { clearTimeout(_closeRPGTimeoutId); _closeRPGTimeoutId = null; }

                    stopCameraLoop();
                    stopNPCMovementLoop();
                    stopConfetti();
                    stopTitleCanvas();
                    stopSplashCanvas();
                    // Clear ALL game-session intervals/timeouts (computer, snake, boss, map, movement)
                    clearAllGameIntervals();
                    // Reset battle state first to stop any animations
                    resetBattleState();

                    // Close modals before closing game
                    closeChangelog();
                    closeCredits();
                    if (typeof closeComputer === "function") closeComputer();
                    if (typeof closeTitleSettings === "function") closeTitleSettings();
                    if (typeof closeExitConfirm === "function") closeExitConfirm();
                    if (typeof window._resetLevelUpChoice === "function") window._resetLevelUpChoice();

                    // Clear game window animation and all inline styles immediately
                    const gameWindow = document.getElementById("rpg-game-window");
                    if (gameWindow) {
                        gameWindow.style.animation = "none";
                        gameWindow.classList.remove("screen-shake");
                        // Clear all inline styles so CSS can work properly next time
                        void gameWindow.offsetWidth;
                        gameWindow.style.animation = "";
                        gameWindow.style.opacity = "";
                        gameWindow.style.transform = "";
                        gameWindow.style.transition = "";
                    }

                    overlay.classList.remove("open");
                    overlay.classList.add("closing");
                    _closeRPGTimeoutId = setTimeout(() => {
                        _closeRPGTimeoutId = null;
                        overlay.classList.remove("closing");
                        if (splash) splash.classList.remove("active");
                        document.body.classList.remove("rpg-active");
                        resetGame();
                        // Reset and reinitialize splash loader for next open
                        resetSplashLoader();
                    }, 600);
                };

                window.returnToTitleMenu = function () {
                    // Stop game loops
                    stopCameraLoop();
                    stopNPCMovementLoop();
                    stopConfetti();
                    stopTitleCanvas();
                    stopSplashCanvas();
                    // Clear ALL game-session intervals/timeouts (computer, snake, boss, map, movement)
                    clearAllGameIntervals();

                    // Reset battle state to stop any animations
                    resetBattleState();

                    // Close computer if open
                    if (typeof closeComputer === "function") closeComputer();
                    // Close all modals if open
                    if (typeof closeTitleSettings === "function") closeTitleSettings();
                    if (typeof closeChangelog === "function") closeChangelog();
                    if (typeof closeCredits === "function") closeCredits();
                    if (typeof closeExitConfirm === "function") closeExitConfirm();

                    // Hide ending screen
                    const endingScreen = document.getElementById("rpg-ending-screen");
                    if (endingScreen) endingScreen.classList.remove("active");

                    // Reset game state
                    resetGame();
                    splashLoaded = false;

                    // Remove zoom-in class from game window
                    const gw = document.getElementById("rpg-game-window");
                    if (gw) {
                        gw.classList.remove("gw-zoom-in");
                        gw.style.animation = "";
                        gw.style.transition = "";
                        gw.style.opacity = "";
                        gw.style.transform = "";
                    }

                    // Show splash screen
                    if (splash) {
                        splash.classList.add("active");
                        splash.style.opacity = "";
                        splash.style.transition = "";
                    }

                    // Reset and restart the splash loader + canvas
                    resetSplashLoader();
                    stopSplashCanvas();
                    setTimeout(() => {
                        initSplashLoader();
                        initSplashCanvas();
                    }, 100);
                };

                window.quitGame = function () { closeRPG(); };

                // ===== EXIT CONFIRM MODAL =====
                let _exitConfirmCallback = null;
                function showExitConfirm(onConfirm) {
                    const modal = document.getElementById('exit-confirm-modal');
                    if (!modal) { if (typeof onConfirm === 'function') onConfirm(); return; }
                    _exitConfirmCallback = typeof onConfirm === 'function' ? onConfirm : null;
                    if (modal.parentElement !== document.body) document.body.appendChild(modal);
                    modal.classList.remove('closing');
                    modal.classList.add('active');
                }
                function closeExitConfirm() {
                    const modal = document.getElementById('exit-confirm-modal');
                    if (!modal) return;
                    modal.classList.add('closing');
                    setTimeout(() => { modal.classList.remove('active', 'closing'); }, 250);
                    _exitConfirmCallback = null;
                }

                // Wire up exit-confirm buttons
                document.getElementById('exit-confirm-yes')?.addEventListener('click', () => {
                    const cb = _exitConfirmCallback;
                    closeExitConfirm();
                    if (cb) cb();
                });
                document.getElementById('exit-confirm-no')?.addEventListener('click', closeExitConfirm);
                document.getElementById('exit-confirm-modal')?.addEventListener('click', (e) => {
                    if (e.target.id === 'exit-confirm-modal') closeExitConfirm();
                });
                document.addEventListener('keydown', (e) => {
                    if (e.key === 'Escape') {
                        const ecModal = document.getElementById('exit-confirm-modal');
                        if (ecModal && ecModal.classList.contains('active')) {
                            e.stopImmediatePropagation();
                            closeExitConfirm();
                        }
                    }
                }, true);

                // Overlay click: splash = direct close, gameplay = confirm dialog
                if (overlay) overlay.addEventListener("click", (e) => {
                    if (e.target !== overlay) return;
                    if (gameState === "SPLASH" || gameState === "TITLE") {
                        closeRPG();
                    } else {
                        showExitConfirm(() => closeRPG());
                    }
                });
                // X button: same logic
                document.getElementById("rpg-close-btn")?.addEventListener("click", () => {
                    if (gameState === "SPLASH" || gameState === "TITLE") {
                        closeRPG();
                    } else {
                        showExitConfirm(() => closeRPG());
                    }
                });

                function showScreen(id) {
                    document.querySelectorAll(".rpg-screen").forEach(s => s.classList.remove("active"));
                    if (id) {
                        const el = document.getElementById(id);
                        if (el) {
                            el.classList.add("active");
                            // Shop-Screens werden von renderNewShopUI selbst gerendert - kein parseEmojis hier
                            if (id !== 'rpg-shop-screen' && id !== 'rpg-skillshop-screen') {
                                parseEmojis(el);
                            }
                        }
                    }
                    // PATCH V: Titel-Partikel beim Anzeigen des Titelmenues (alle Pfade)
                    if (id === "rpg-title-screen") {
                        if (typeof spawnTitleParticles === "function") spawnTitleParticles();
                        // PATCH AA: Continue-Button-Sichtbarkeit IMMER aktualisieren (Bugfix)
                        if (typeof updateTitleMenu === "function") updateTitleMenu();
                        // BUGFIX: Title-Button-Animationen zurücksetzen (PopIn erneut abspielen)
                        document.querySelectorAll('#rpg-title-screen .title-btn.bv-managed').forEach(function(btn) {
                            btn.classList.remove('bv-state-idle', 'bv-state-hover', 'bv-state-press', 'bv-state-release', 'bv-state-click', 'bv-btn-entrance');
                            btn.offsetHeight; // force reflow
                            btn.classList.add('bv-state-idle', 'bv-btn-entrance');
                            // PopIn-Klasse nach Animationsende entfernen, damit Breathing übernimmt
                            var btnDelay = parseInt(getComputedStyle(btn).getPropertyValue('--btn-pop-delay')) || 80;
                            setTimeout(function() {
                                btn.classList.remove('bv-btn-entrance');
                            }, btnDelay + 620);
                        });
                    }
                }

                // ===== SPLASH SCREEN REDESIGN v2.0 =====
                let splashLoaded = false;
                let loadProgress = 0;
                let loadTimeoutId = null;
                let splashCanvasCtx = null;
                let splashAnimId = null;
                let splashParticles = [];
                let titleCanvasCtx = null;
                let titleAnimId = null;
                let titleParticles = [];
                let splashResizeHandler = null;
                let titleResizeHandler = null;
                let splashCleanupMouse = null;

                // Race-condition guards: store timeout IDs so we can cancel stale ones
                let _closeRPGTimeoutId = null;
                let _openRPGTimeout1 = null;
                let _openRPGTimeout2 = null;

                // Master cleanup: clear ALL game-session intervals/timeouts
                function clearAllGameIntervals() {
                    if (typeof snakeGame !== "undefined" && snakeGame) { clearInterval(snakeGame); snakeGame = null; }
                    if (typeof computerTimeInterval !== "undefined" && computerTimeInterval) { clearInterval(computerTimeInterval); computerTimeInterval = null; }
                    if (typeof computerClockInterval !== "undefined" && computerClockInterval) { clearInterval(computerClockInterval); computerClockInterval = null; }
                    if (typeof bossSpeechTimeout !== "undefined" && bossSpeechTimeout) { clearTimeout(bossSpeechTimeout); bossSpeechTimeout = null; }
                    if (typeof mapTransitionTimeout !== "undefined" && mapTransitionTimeout) { clearTimeout(mapTransitionTimeout); mapTransitionTimeout = null; }
                    if (typeof moveInterval !== "undefined" && moveInterval) { clearInterval(moveInterval); moveInterval = null; }
                }

                let splashMouseX = -1000, splashMouseY = -1000;
                function initSplashCanvas() {
                    const canvas = document.getElementById("splash-canvas");
                    if (!canvas) return;
                    const ctx = canvas.getContext("2d");
                    if (!ctx) return;
                    splashCanvasCtx = ctx;

                    function resize() {
                        canvas.width = window.innerWidth;
                        canvas.height = window.innerHeight;
                    }
                    resize();
                    splashResizeHandler = resize;
                    window.addEventListener("resize", splashResizeHandler);

                    // Mouse tracking for repulsion effect
                    function onMouseMove(e) {
                        splashMouseX = e.clientX;
                        splashMouseY = e.clientY;
                    }
                    function onMouseLeave() {
                        splashMouseX = -1000;
                        splashMouseY = -1000;
                    }
                    canvas.addEventListener("mousemove", onMouseMove);
                    canvas.addEventListener("mouseleave", onMouseLeave);
                    // Store cleanup for mouse listeners
                    const cleanupMouse = function() {
                        canvas.removeEventListener("mousemove", onMouseMove);
                        canvas.removeEventListener("mouseleave", onMouseLeave);
                    };

                    const prefersReducedMotion = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
                    const count = prefersReducedMotion ? 0 : Math.min(100, Math.floor((canvas.width * canvas.height) / 12000));
                    splashParticles = [];
                    const officeColors = [
                        { r: 74, g: 159, b: 255 },   // blue
                        { r: 124, g: 92, b: 224 },    // purple
                        { r: 148, g: 163, b: 184 },   // gray
                        { r: 240, g: 192, b: 64 },    // gold
                        { r: 200, g: 180, b: 160 },   // warm paper
                        { r: 6, g: 182, b: 212 }      // cyan
                    ];
                    for (let i = 0; i < count; i++) {
                        const rnd = Math.random();
                        const shape = rnd > 0.75 ? 'clip' : rnd > 0.55 ? 'folder' : rnd > 0.3 ? 'doc' : 'dot';
                        const col = officeColors[Math.floor(Math.random() * officeColors.length)];
                        splashParticles.push({
                            x: Math.random() * canvas.width,
                            y: Math.random() * canvas.height,
                            vx: (Math.random() - 0.5) * 0.3,
                            vy: -(Math.random() * 0.15 + 0.04),
                            r: Math.random() * 1.8 + 0.4,
                            a: Math.random() * 0.35 + 0.08,
                            s: Math.random() * 1.5 + 0.8,
                            shape: shape,
                            col: col,
                            rot: Math.random() * Math.PI * 2,
                            rotV: (Math.random() - 0.5) * 0.005,
                            trail: [],
                            shimmer: Math.random() * Math.PI * 2,
                            shimmerV: Math.random() * 0.02 + 0.005
                        });
                    }

                    function draw() {
                        if (!splashCanvasCtx) return;
                        const c = splashCanvasCtx;
                        const w = canvas.width, h = canvas.height;
                        const time = Date.now() * 0.001;

                        // Fade effect for trails (semi-transparent clear)
                        c.fillStyle = "rgba(10, 14, 28, 0.15)";
                        c.fillRect(0, 0, w, h);

                        // Phase 0: Update particles + trails + mouse repulsion
                        for (const p of splashParticles) {
                            // Store trail position
                            if (p.trail.length > 5) p.trail.shift();
                            p.trail.push({ x: p.x, y: p.y });

                            // Mouse repulsion (gentle push away)
                            const mdx = p.x - splashMouseX;
                            const mdy = p.y - splashMouseY;
                            const mdist2 = mdx * mdx + mdy * mdy;
                            const repelRadius = 120;
                            if (mdist2 < repelRadius * repelRadius && mdist2 > 0) {
                                const mdist = Math.sqrt(mdist2);
                                const force = (1 - mdist / repelRadius) * 0.8;
                                p.vx += (mdx / mdist) * force;
                                p.vy += (mdy / mdist) * force;
                            }

                            // Dampen velocity
                            p.vx *= 0.99;
                            p.vy *= 0.99;

                            p.x += p.vx;
                            p.y += p.vy;
                            p.rot += p.rotV;
                            p.shimmer += p.shimmerV;

                            // Wrap around
                            if (p.y < -10) { p.y = h + 10; p.x = Math.random() * w; p.trail = []; }
                            if (p.x < -10) { p.x = w + 10; p.trail = []; }
                            if (p.x > w + 10) { p.x = -10; p.trail = []; }
                        }

                        // Phase 1: Draw connection lines (optimized)
                        const maxDist2 = 150 * 150;
                        for (let i = 0; i < splashParticles.length; i++) {
                            const pi = splashParticles[i];
                            for (let j = i + 1; j < splashParticles.length; j++) {
                                const pj = splashParticles[j];
                                const dx = pi.x - pj.x;
                                if (Math.abs(dx) > 150) continue;
                                const dy = pi.y - pj.y;
                                const dist2 = dx * dx + dy * dy;
                                if (dist2 < maxDist2) {
                                    const dist = Math.sqrt(dist2);
                                    const alpha = (1 - dist / 150) * 0.08;
                                    const ci = pi.col;
                                    const cj = pj.col;
                                    const mr = Math.floor((ci.r + cj.r) / 2);
                                    const mg = Math.floor((ci.g + cj.g) / 2);
                                    const mb = Math.floor((ci.b + cj.b) / 2);
                                    c.beginPath();
                                    c.moveTo(pi.x, pi.y);
                                    c.lineTo(pj.x, pj.y);
                                    c.strokeStyle = `rgba(${mr}, ${mg}, ${mb}, ${alpha})`;
                                    c.lineWidth = 0.6;
                                    c.stroke();
                                }
                            }
                        }

                        // Phase 2: Draw particles + trails
                        for (const p of splashParticles) {
                            const { r: cr, g: cg, b: cb } = p.col;
                            const shimmerAlpha = 0.8 + 0.2 * Math.sin(p.shimmer);

                            // Draw trail (fading copies)
                            for (let t = 0; t < p.trail.length; t++) {
                                const tp = p.trail[t];
                                const trailAlpha = (t / p.trail.length) * 0.15;
                                const trailSize = p.r * (0.3 + 0.3 * (t / p.trail.length));
                                c.beginPath();
                                c.arc(tp.x, tp.y, trailSize, 0, Math.PI * 2);
                                c.fillStyle = `rgba(${cr}, ${cg}, ${cb}, ${trailAlpha})`;
                                c.fill();
                            }

                            if (p.shape === 'doc') {
                                const dw = p.r * 4;
                                const dh = p.r * 5.5;
                                c.save();
                                c.translate(p.x, p.y);
                                c.rotate(p.rot);
                                c.globalAlpha = p.a * 0.6 * shimmerAlpha;
                                c.fillStyle = `rgba(${cr}, ${cg}, ${cb}, 0.06)`;
                                c.strokeStyle = `rgba(${cr}, ${cg}, ${cb}, ${p.a * 0.2})`;
                                c.lineWidth = 0.5;
                                c.fillRect(-dw/2, -dh/2, dw, dh);
                                c.strokeRect(-dw/2, -dh/2, dw, dh);
                                c.beginPath();
                                c.moveTo(dw/2 - 3, -dh/2);
                                c.lineTo(dw/2, -dh/2 + 3);
                                c.lineTo(dw/2 - 3, -dh/2 + 3);
                                c.closePath();
                                c.fillStyle = `rgba(${cr}, ${cg}, ${cb}, ${p.a * 0.1})`;
                                c.fill();
                                c.restore();

                            } else if (p.shape === 'clip') {
                                // Paperclip shape
                                c.save();
                                c.translate(p.x, p.y);
                                c.rotate(p.rot);
                                c.globalAlpha = p.a * 0.5 * shimmerAlpha;
                                c.strokeStyle = `rgba(${cr}, ${cg}, ${cb}, ${p.a * 0.25})`;
                                c.lineWidth = 0.7;
                                const cs = p.r * 2.5;
                                c.beginPath();
                                c.arc(0, -cs * 0.3, cs * 0.5, Math.PI, 0);
                                c.arc(0, cs * 0.3, cs * 0.5, 0, Math.PI);
                                c.stroke();
                                c.beginPath();
                                c.moveTo(-cs * 0.5, -cs * 0.3);
                                c.lineTo(-cs * 0.5, cs * 0.3);
                                c.stroke();
                                c.restore();

                            } else if (p.shape === 'folder') {
                                // Folder tab shape
                                c.save();
                                c.translate(p.x, p.y);
                                c.rotate(p.rot);
                                c.globalAlpha = p.a * 0.5 * shimmerAlpha;
                                const fw = p.r * 4;
                                const fh = p.r * 3;
                                c.fillStyle = `rgba(${cr}, ${cg}, ${cb}, 0.05)`;
                                c.strokeStyle = `rgba(${cr}, ${cg}, ${cb}, ${p.a * 0.18})`;
                                c.lineWidth = 0.5;
                                // Tab
                                c.beginPath();
                                c.moveTo(-fw/2, -fh/2);
                                c.lineTo(-fw/2 + fw * 0.3, -fh/2 - fh * 0.25);
                                c.lineTo(-fw/2 + fw * 0.5, -fh/2 - fh * 0.25);
                                c.lineTo(-fw/2 + fw * 0.5, -fh/2);
                                c.closePath();
                                c.fill();
                                c.stroke();
                                // Body
                                c.fillRect(-fw/2, -fh/2, fw, fh);
                                c.strokeRect(-fw/2, -fh/2, fw, fh);
                                c.restore();

                            } else {
                                // Dot particle with glow
                                const grad = c.createRadialGradient(p.x, p.y, 0, p.x, p.y, p.r * 3);
                                grad.addColorStop(0, `rgba(${cr}, ${cg}, ${cb}, ${p.a * shimmerAlpha})`);
                                grad.addColorStop(0.5, `rgba(${cr}, ${cg}, ${cb}, ${p.a * shimmerAlpha * 0.3})`);
                                grad.addColorStop(1, `rgba(${cr}, ${cg}, ${cb}, 0)`);
                                c.beginPath();
                                c.arc(p.x, p.y, p.r * 3, 0, Math.PI * 2);
                                c.fillStyle = grad;
                                c.fill();

                                if (p.r > 1.0) {
                                    c.beginPath();
                                    c.arc(p.x, p.y, p.r * 0.5, 0, Math.PI * 2);
                                    c.fillStyle = `rgba(${cr}, ${cg}, ${cb}, ${p.a * 0.5})`;
                                    c.fill();
                                }
                            }
                        }

                        // Phase 3: Occasional paper clip shapes (subtle curved lines)
                        const clipCount = Math.floor(splashParticles.length / 25);
                        for (let i = 0; i < clipCount; i++) {
                            const idx = i * 25 + Math.floor(time * 2) % 25;
                            if (idx < splashParticles.length) {
                                const p = splashParticles[idx];
                                const { r: cr, g: cg, b: cb } = p.col;
                                c.save();
                                c.globalAlpha = p.a * 0.12;
                                c.strokeStyle = `rgba(${cr}, ${cg}, ${cb}, ${p.a * 0.12})`;
                                c.lineWidth = 0.6;
                                c.beginPath();
                                c.arc(p.x + 4, p.y, 6, 0, Math.PI * 1.5);
                                c.stroke();
                                c.beginPath();
                                c.moveTo(p.x + 4, p.y + 6);
                                c.lineTo(p.x + 4, p.y + 12);
                                c.stroke();
                                c.restore();
                            }
                        }

                        splashAnimId = requestAnimationFrame(draw);
                    }
                    draw();

                    // Return cleanup function for mouse listeners
                    splashCleanupMouse = cleanupMouse;
                }

                function stopSplashCanvas() {
                    if (splashAnimId) {
                        cancelAnimationFrame(splashAnimId);
                        splashAnimId = null;
                    }
                    if (splashResizeHandler) {
                        window.removeEventListener("resize", splashResizeHandler);
                        splashResizeHandler = null;
                    }
                    if (splashCleanupMouse) {
                        splashCleanupMouse();
                        splashCleanupMouse = null;
                    }
                    splashCanvasCtx = null;
                }

                function initTitleCanvas() {
                    const canvas = document.getElementById("title-canvas");
                    if (!canvas) return;
                    const ctx = canvas.getContext("2d");
                    if (!ctx) return;
                    titleCanvasCtx = ctx;

                    function resize() {
                        canvas.width = window.innerWidth;
                        canvas.height = window.innerHeight;
                    }
                    resize();
                    titleResizeHandler = resize;
                    window.addEventListener("resize", titleResizeHandler);

                    const prefersReducedMotion = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
                    const count = prefersReducedMotion ? 0 : Math.min(40, Math.floor((canvas.width * canvas.height) / 25000));
                    titleParticles = [];
                    const colors = [
                        { r: 74, g: 159, b: 255 },
                        { r: 147, g: 51, b: 234 },
                        { r: 148, g: 163, b: 184 },
                        { r: 6, g: 182, b: 212 }
                    ];
                    for (let i = 0; i < count; i++) {
                        titleParticles.push({
                            x: Math.random() * canvas.width,
                            y: Math.random() * canvas.height,
                            vx: (Math.random() - 0.5) * 0.2,
                            vy: -(Math.random() * 0.1 + 0.02),
                            r: Math.random() * 1.5 + 0.5,
                            a: Math.random() * 0.3 + 0.05,
                            col: colors[Math.floor(Math.random() * colors.length)]
                        });
                    }

                    function draw() {
                        if (!titleCanvasCtx) return;
                        const c = titleCanvasCtx;
                        const w = canvas.width, h = canvas.height;

                        c.clearRect(0, 0, w, h);

                        for (const p of titleParticles) {
                            p.x += p.vx;
                            p.y += p.vy;
                            if (p.y < -10) { p.y = h + 10; p.x = Math.random() * w; }
                            if (p.x < -10) p.x = w + 10;
                            if (p.x > w + 10) p.x = -10;

                            const grad = c.createRadialGradient(p.x, p.y, 0, p.x, p.y, p.r * 3);
                            grad.addColorStop(0, `rgba(${p.col.r}, ${p.col.g}, ${p.col.b}, ${p.a})`);
                            grad.addColorStop(1, `rgba(${p.col.r}, ${p.col.g}, ${p.col.b}, 0)`);
                            c.beginPath();
                            c.arc(p.x, p.y, p.r * 3, 0, Math.PI * 2);
                            c.fillStyle = grad;
                            c.fill();
                        }

                        // Connection lines (optimized: squared distance, skip sqrt)
                        const maxDist2 = 100 * 100;
                        for (let i = 0; i < titleParticles.length; i++) {
                            const pi = titleParticles[i];
                            for (let j = i + 1; j < titleParticles.length; j++) {
                                const pj = titleParticles[j];
                                const dx = pi.x - pj.x;
                                if (Math.abs(dx) > 100) continue;
                                const dy = pi.y - pj.y;
                                const dist2 = dx * dx + dy * dy;
                                if (dist2 < maxDist2) {
                                    const dist = Math.sqrt(dist2);
                                    c.beginPath();
                                    c.moveTo(pi.x, pi.y);
                                    c.lineTo(pj.x, pj.y);
                                    c.strokeStyle = `rgba(74, 159, 255, ${(1 - dist / 100) * 0.04})`;
                                    c.lineWidth = 0.5;
                                    c.stroke();
                                }
                            }
                        }

                        titleAnimId = requestAnimationFrame(draw);
                    }
                    draw();
                }

                function stopTitleCanvas() {
                    if (titleAnimId) {
                        cancelAnimationFrame(titleAnimId);
                        titleAnimId = null;
                    }
                    if (titleResizeHandler) {
                        window.removeEventListener("resize", titleResizeHandler);
                        titleResizeHandler = null;
                    }
                    titleCanvasCtx = null;
                }

                function resetSplashLoader() {
                    if (loadTimeoutId) {
                        clearTimeout(loadTimeoutId);
                        loadTimeoutId = null;
                    }

                    splashLoaded = false;
                    loadProgress = 0;

                    const fill = document.getElementById("splash-loader-fill");
                    if (fill) fill.style.width = "0%";

                    const label = document.getElementById("splash-loader-label");
                    if (label) label.textContent = "Wird geladen";

                    const pct = document.getElementById("splash-loader-pct");
                    if (pct) pct.textContent = "0%";

                    const start = document.getElementById("splash-start");
                    if (start) start.classList.remove("visible");
                }

                function initSplashLoader() {
                    const fill = document.getElementById("splash-loader-fill");
                    const label = document.getElementById("splash-loader-label");
                    const pct = document.getElementById("splash-loader-pct");
                    const start = document.getElementById("splash-start");

                    if (!fill) return;

                    resetSplashLoader();

                    const loadSteps = [
                        { progress: 12, delay: 180 },
                        { progress: 25, delay: 320 },
                        { progress: 38, delay: 260 },
                        { progress: 50, delay: 380 },
                        { progress: 62, delay: 300 },
                        { progress: 74, delay: 360 },
                        { progress: 85, delay: 420 },
                        { progress: 93, delay: 280 },
                        { progress: 100, delay: 500 }
                    ];

                    let currentStep = 0;

                    function updateLoader() {
                        if (currentStep >= loadSteps.length) {
                            splashLoaded = true;
                            if (label) label.textContent = "Bereit";
                            if (pct) pct.textContent = "100%";
                            if (start) start.classList.add("visible");
                            return;
                        }

                        const step = loadSteps[currentStep];
                        loadProgress = step.progress;

                        fill.style.width = loadProgress + "%";
                        if (pct) pct.textContent = loadProgress + "%";

                        if (label) {
                            if (loadProgress < 25) {
                                label.textContent = "Lade Assets";
                            } else if (loadProgress < 50) {
                                label.textContent = "Initialisiere Spiel";
                            } else if (loadProgress < 75) {
                                label.textContent = "Komprimiere Daten";
                            } else if (loadProgress < 95) {
                                label.textContent = "Finalisiere";
                            } else {
                                label.textContent = "Startklar";
                            }
                        }

                        currentStep++;
                        loadTimeoutId = setTimeout(updateLoader, step.delay);
                    }

                    loadTimeoutId = setTimeout(updateLoader, 400);
                }

                function skipSplash() {
                    if (gameState !== "SPLASH") return;
                    if (!splashLoaded) return;

                    stopSplashCanvas();

                    if (splash) {
                        splash.style.transition = "opacity 0.4s ease-out";
                        splash.style.opacity = "0";
                    }
                    setTimeout(() => {
                        if (splash) {
                            splash.classList.remove("active");
                            splash.style.opacity = "";
                            splash.style.transition = "";
                        }
                        showScreen("rpg-title-screen");
                        stopTitleCanvas();
                        initTitleCanvas();
                        if (typeof spawnTitleParticles === "function") spawnTitleParticles();
                        gameState = "TITLE";
                        updateTitleMenu();
                    }, 400);
                }

                // Event listeners for splash
                document.getElementById("splash-start-btn")?.addEventListener("click", (e) => { e.preventDefault(); e.stopPropagation(); skipSplash(); });
                if (splash) {
                    splash.addEventListener("click", (e) => {
                        if (e.target.closest(".splash-btn, .splash-start, .splash-meta, #rpg-close-btn")) return;
                        if (gameState === "SPLASH" && splashLoaded) skipSplash();
                    });
                    splash.addEventListener("touchend", (e) => {
                        if (e.target.closest(".splash-btn, .splash-start, .splash-meta, #rpg-close-btn")) return;
                        if (gameState === "SPLASH" && splashLoaded) { e.preventDefault(); skipSplash(); }
                    }, { passive: false });
                }

                // ===== TITLE MENU =====
                function updateTitleMenu() {
                    const continueBtn = document.getElementById("title-continue");
                    const deleteBtn = document.getElementById("title-delete-save");
                    const hasSave = hasSaveFile();

                    if (continueBtn) {
                        // Während der Löschanimation darf der Button nicht per Update wieder "normal" gesetzt werden.
                        if (continueBtn.classList.contains("continue-deleting")) {
                            continueBtn.style.display = "flex";
                            continueBtn.setAttribute("aria-disabled", "true");
                        } else {
                            continueBtn.style.display = hasSave ? "flex" : "none";
                            continueBtn.toggleAttribute("disabled", !hasSave);
                            continueBtn.setAttribute("aria-disabled", hasSave ? "false" : "true");
                        }
                    }

                    if (deleteBtn) {
                        const deleteIsAnimating = _deleteFxRunning || deleteBtn.classList.contains("deleting") || deleteBtn.classList.contains("crumble");
                        // Speicherdaten löschen nur anzeigen, wenn auch wirklich ein Save existiert.
                        // Während der Animation bleibt er sichtbar, damit der Crumble sauber fertig läuft.
                        deleteBtn.style.display = (hasSave || deleteIsAnimating) ? "flex" : "none";
                        deleteBtn.toggleAttribute("disabled", !hasSave && !deleteIsAnimating);
                        deleteBtn.setAttribute("aria-disabled", (hasSave || deleteIsAnimating) ? "false" : "true");
                    }
                }


                function startNewGame() {
                    if (_deleteFxRunning || isTransitioning || gameState === "NAME" || gameState === "MAP") return;
                    // Reset state so no previous name/signature persists
                    resetGame();
                    startMapTransition();
                    setTimeout(() => {
                        showScreen("rpg-name-screen");
                        gameState = "NAME";
                        // ensure input is focused and previews are reset
                        const nameInp = document.getElementById("rpg-name-input");
                        if (nameInp) { nameInp.value = ""; nameInp.focus(); }
                        const paper = document.querySelector('.contract-paper');
                        if (paper) paper.scrollTop = 0;
                    }, 550);
                }


                function continueGame() {
                    if (_deleteFxRunning || isTransitioning || gameState !== "TITLE") return;

                    const save = getSaveFile();
                    if (!save || typeof save !== "object") {
                        updateTitleMenu();
                        return;
                    }

                    // Restore gender and department first
                    playerGender = save.gender || "m";
                    playerDept = save.dept || "einkauf";

                    // Restore player object with all properties
                    player = (save.player && typeof save.player === "object") ? save.player : {};
                    window.player = player; // BUGFIX: globale Shop-Referenz nach Fortfahren aktualisieren
                    player.name = save.name || player.name || "Held";

                    // Ensure player has gender, dept, and sprite
                    player.gender = playerGender;
                    player.dept = playerDept;
                    player.sprite = player.sprite || GENDER_SPRITES[playerGender] || "🧑‍💼";
                    player.unlockedSkills = save.unlockedSkills || player.unlockedSkills || ["tacker", "kaffee", "meeting"];

                    // Restore location; kaputte/alte Saves landen sicher im Büro statt in einem leeren Map-State.
                    currentMapId = MAPS[save.currentMapId] ? save.currentMapId : "buero";

                    // Spielerposition für das Laden vormerken (kompatibel mit
                    // altem Format: Fallback auf player.x/player.y).
                    const _savedX = (save.playerPos && typeof save.playerPos.x === "number")
                        ? save.playerPos.x : player.x;
                    const _savedY = (save.playerPos && typeof save.playerPos.y === "number")
                        ? save.playerPos.y : player.y;
                    const _savedFacing = (save.playerPos && save.playerPos.facing)
                        ? save.playerPos.facing : (player.facing || "right");
                    if (typeof _savedX === "number" && typeof _savedY === "number") {
                        pendingLoadPos = { mapId: currentMapId, x: _savedX, y: _savedY, facing: _savedFacing };
                    } else {
                        pendingLoadPos = null;
                    }

                    // Restore game progress
                    defeatedEnemies = new Set(Array.isArray(save.defeatedEnemies) ? save.defeatedEnemies : []);
                    openedChests = new Set(Array.isArray(save.openedChests) ? save.openedChests : []);
                    metNPCs = Array.isArray(save.metNPCs) ? save.metNPCs : [];
                    battleCount = Number(save.battleCount) || 0;
                    chestCount = Number(save.chestCount) || 0;

                    // Update ALL visible name/sprite fields immediately
                    const _upd = (id, val) => { const el = document.getElementById(id); if (el) el.innerText = val; };
                    _upd("hud-player-name", player.name);
                    _upd("player-sprite-name", player.name);
                    _upd("battle-player-name", player.name);
                    _upd("menu-player-name", player.name);
                    _upd("vs-player-name", player.name);

                    _upd("hud-portrait", player.sprite);
                    _upd("menu-portrait", player.sprite);
                    _upd("battle-portrait", player.sprite);
                    _upd("vs-player-sprite", player.sprite);

                    const spriteBody = document.querySelector("#rpg-player .sprite-body");
                    if (spriteBody) spriteBody.innerText = player.sprite;

                    const battlePortrait = document.querySelector(".player-portrait-battle");
                    if (battlePortrait) battlePortrait.innerText = player.sprite;

                    _upd("menu-player-title", (GENDER_TITLES[playerGender] || GENDER_TITLES.m) + " - " + (DEPT_NAMES[playerDept] || DEPT_NAMES.einkauf));

                    if (mapTrans) {
                        const transText = mapTrans.querySelector('.transition-text');
                        if (transText) transText.innerText = MAPS[currentMapId]?.name || 'Laden...';
                    }
                    currentEnemy = null;
                    startMapTransition();
                    setTimeout(() => {
                        showScreen("rpg-game-screen");
                        loadMap(currentMapId);
                        gameState = "MAP";
                        updateHUD();
                    }, 550);
                }


                let _deleteFxRunning = false;
                function playDeleteSaveFx(onDone) {
                    const titleScreen = document.getElementById("rpg-title-screen");
                    const deleteBtn = document.getElementById("title-delete-save");
                    const continueBtn = document.getElementById("title-continue");

                    const finish = () => {
                        _deleteFxRunning = false;
                        window.BVDeleteFxRunning = false;
                        if (onDone) onDone();
                    };

                    if (!titleScreen) {
                        finish();
                        return;
                    }

                    // === v7.10.6: robuste Continue-Löschanimation ===
                    let continueAnimated = false;
                    const continueVisible = continueBtn && continueBtn.style.display !== "none" &&
                        (!window.getComputedStyle || getComputedStyle(continueBtn).display !== "none");
                    if (continueVisible && !continueBtn.classList.contains("continue-deleting")) {
                        continueAnimated = true;
                        continueBtn.classList.add("continue-deleting");
                        continueBtn.setAttribute("aria-disabled", "true");

                        // After the CSS animation finishes, hide it permanently
                        setTimeout(() => {
                            if (continueBtn) {
                                continueBtn.style.display = "none";
                                continueBtn.classList.remove("continue-deleting");
                                continueBtn.toggleAttribute("disabled", true);
                            }
                        }, 1450);
                    }

                    // Visual feedback on the delete button
                    if (deleteBtn) {
                        deleteBtn.style.transition = "all 0.3s ease";
                        deleteBtn.style.opacity = "0.6";
                        deleteBtn.style.transform = "scale(0.95)";
                        deleteBtn.setAttribute("aria-disabled", "true");
                    }

                    // Create the dramatic delete overlay (data rain etc.)
                    const overlay = document.createElement("div");
                    overlay.className = "delete-fx-overlay";

                    const flash = document.createElement("div");
                    flash.className = "delete-fx-flash";
                    overlay.appendChild(flash);

                    const scan = document.createElement("div");
                    scan.className = "delete-fx-scan";
                    overlay.appendChild(scan);

                    // Falling 0/1 bits
                    const bitCount = 38;
                    for (let i = 0; i < bitCount; i++) {
                        const bit = document.createElement("span");
                        bit.className = "delete-fx-bit";
                        bit.textContent = Math.random() > 0.5 ? "1" : "0";
                        bit.style.left = (Math.random() * 100) + "%";
                        bit.style.setProperty("--dur", (0.65 + Math.random() * 0.75).toFixed(2) + "s");
                        bit.style.setProperty("--delay", (Math.random() * 0.45).toFixed(2) + "s");
                        bit.style.setProperty("--fall", (240 + Math.random() * 260).toFixed(0) + "px");
                        bit.style.fontSize = (0.85 + Math.random() * 1.15).toFixed(2) + "rem";
                        overlay.appendChild(bit);
                    }

                    const stamp = document.createElement("div");
                    stamp.className = "delete-fx-stamp";
                    stamp.textContent = "GELÖSCHT";
                    overlay.appendChild(stamp);

                    titleScreen.appendChild(overlay);

                    if (deleteBtn) {
                        deleteBtn.classList.add("deleting");
                        setTimeout(() => {
                            if (deleteBtn) deleteBtn.classList.add("crumble");
                        }, 420);
                    }

                    // Cleanup + callback. Wir warten bis Continue-Animation + Overlay fertig sind.
                    const totalWait = continueAnimated ? 1750 : 1400;

                    setTimeout(() => {
                        if (overlay && overlay.parentNode) overlay.parentNode.removeChild(overlay);

                        if (deleteBtn) {
                            deleteBtn.classList.remove("deleting", "crumble");
                            deleteBtn.style.transition = "";
                            deleteBtn.style.opacity = "";
                            deleteBtn.style.transform = "";
                        }

                        finish();
                    }, totalWait);
                }


                function deleteSaveData() {
                    if (_deleteFxRunning || gameState !== "TITLE") return;
                    if (!hasSaveFile()) {
                        updateTitleMenu();
                        return;
                    }
                    if (confirm("Willst du wirklich alle Speicherdaten löschen?")) {
                        _deleteFxRunning = true;
                        window.BVDeleteFxRunning = true;
                        updateTitleMenu();
                        playDeleteSaveFx(() => {
                            deleteSaveFile();
                            updateTitleMenu();
                            showMessage("Speicherdaten wurden gelöscht.", "🗑️ Gelöscht", "🗑️");
                        });
                    }
                }


