                // ARENA PATCH JS: SEBASTIANO SECRET ROOM SYSTEM
                // ============================================================
                function enterSecretRoomFromHiddenSpot() {
                    if (isTransitioning || gameState === "TRANSITION") return;
                    if (interactionHint) interactionHint.classList.remove("visible");
                    pendingLoadPos = { mapId: "secret_room", x: 6, y: 10, facing: "up" };
                    loadMap("secret_room", true);
                    setTimeout(() => {
                        if (currentMapId === "secret_room") {
                            showMessage("Du schlüpfst hinter der Kaffeeecke durch einen geheimen Gang...", "Geheimer Eingang", "✨");
                            queueMessage("Vor dir liegt ein Raum, den keine Karte kennt.", "Geheimer Eingang", "🗝️");
                        }
                    }, 1680);
                }

                window.checkSecretRoomEntrance = function() {
                    if (currentMapId !== "buero") return;
                    if (player.x !== 26 || player.y !== 7) return;
                    if (isTransitioning || gameState !== "MAP") return;
                    if (window._bvSecretRoomPromptOpen) return;
                    window._bvSecretRoomPromptOpen = true;

                    setTimeout(() => {
                        if (currentMapId !== "buero" || player.x !== 26 || player.y !== 7 || gameState !== "MAP") {
                            window._bvSecretRoomPromptOpen = false;
                            return;
                        }
                        window.showChoice("Hinter der Kaffeemaschine zieht kalte Luft aus einer kaum sichtbaren Wandfuge. Hineinschlüpfen?", [
                            { label: "Ja, geheimen Gang betreten", value: "enter", hint: "🗝️" },
                            { label: "Nein, lieber nicht", value: "no", hint: "↩" }
                        ], "Geheimer Eingang", "✨", (val) => {
                            window._bvSecretRoomPromptOpen = false;
                            if (val === "enter") enterSecretRoomFromHiddenSpot();
                            else showMessage("Du trittst von der Wandfuge zurück. Vielleicht später...", "Geheimer Eingang", "✨");
                        });
                    }, 180);
                };

                function giveSebastianoShopItem(itemId, amount = 1) {
                    if (!player.inventory) player.inventory = [];
                    const itemData = SHOP_ITEMS.find(item => item.id === itemId);
                    if (!itemData) return false;
                    const existing = player.inventory.find(i => i.id === itemId);
                    if (existing) existing.count += amount;
                    else player.inventory.push({
                        id: itemData.id,
                        name: itemData.icon + " " + itemData.name,
                        heal: itemData.heal || 0,
                        mpHeal: itemData.mpHeal || 0,
                        atkBoost: itemData.atkBoost || 0,
                        defBoost: itemData.defBoost || 0,
                        hpBoost: itemData.hpBoost || 0,
                        mpBoost: itemData.mpBoost || 0,
                        count: amount
                    });
                    return true;
                }

