                /* ============================================================
                   ARENA PATCH JS: EASTER EVENT ROBUST FIX
                   - normalisiert Patricks Quest-State
                   - lädt übrige Eier nach Spielstand laden korrekt wieder auf die Map
                   - ersetzt fragile Easter-Funktionen durch robuste Varianten
                   ============================================================ */
                function getEasterEggTotal() {
                    return Object.values(EASTER_EGGS || {}).reduce((sum, arr) => sum + (Array.isArray(arr) ? arr.length : 0), 0);
                }

                function normalizeEasterEventState() {
                    if (!player.questState) player.questState = {};
                    const total = getEasterEggTotal();
                    const state = easterEventState && typeof easterEventState === 'object' ? easterEventState : {};
                    const collected = Array.isArray(state.collectedEggs) ? state.collectedEggs : [];
                    easterEventState = {
                        active: !!state.active,
                        completed: !!state.completed,
                        collectedEggs: Array.from(new Set(collected.filter(Boolean).map(String))),
                        totalEggs: total
                    };

                    if (player.questState.easterEvent === "active") {
                        easterEventState.active = true;
                    }
                    if (player.questState.easterEvent === "completed") {
                        easterEventState.active = false;
                        easterEventState.completed = true;
                    }
                    if (easterEventState.collectedEggs.length >= total && total > 0 && player.questState.easterEvent === "active") {
                        easterEventState.completed = true;
                    }
                    return easterEventState;
                }

                function refreshEasterEventAfterMapLoad() {
                    normalizeEasterEventState();
                    spawnEasterEggs();
                    updateEasterUI();
                    checkNearbyInteractables();
                }

                function spawnEasterEggs() {
                    if (!easterEggLayer) return;
                    normalizeEasterEventState();
                    easterEggLayer.innerHTML = "";
                    currentEasterEggs = [];

                    if (!easterEventState.active || easterEventState.completed || player.questState?.easterEvent === "completed") {
                        updateEasterUI();
                        return;
                    }

                    const mapEggs = EASTER_EGGS[currentMapId] || [];
                    mapEggs.forEach((egg, i) => {
                        const eggKey = `${currentMapId}_${egg.x}_${egg.y}`;
                        if (easterEventState.collectedEggs.includes(eggKey)) return;
                        const runtimeEgg = { ...egg, key: eggKey };
                        currentEasterEggs.push(runtimeEgg);
                        const el = document.createElement("div");
                        el.className = "map-easter-egg";
                        el.innerHTML = `<div class="easter-egg-glow"></div><div class="easter-egg-sprite">${egg.color || "🥚"}</div>`;
                        placeMapElement(el, egg.x, egg.y, "egg");
                        el.dataset.eggKey = eggKey;
                        el.dataset.eggIndex = i;
                        el.addEventListener("click", () => {
                            const dist = Math.abs(player.x - egg.x) + Math.abs(player.y - egg.y);
                            if (dist <= 1 && gameState === "MAP") collectEasterEgg(runtimeEgg, el, eggKey);
                        });
                        easterEggLayer.appendChild(el);
                    });
                    parseEmojis(easterEggLayer);
                    updateEasterUI();
                }

                function collectEasterEgg(egg, el, eggKey) {
                    normalizeEasterEventState();
                    eggKey = eggKey || egg?.key || `${currentMapId}_${egg.x}_${egg.y}`;
                    if (!egg || easterEventState.collectedEggs.includes(eggKey)) return;

                    easterEventState.collectedEggs.push(eggKey);
                    easterEventState.collectedEggs = Array.from(new Set(easterEventState.collectedEggs));

                    if (el) {
                        el.classList.add("collected");
                        const sprite = el.querySelector(".easter-egg-sprite");
                        if (sprite) sprite.innerText = "✨";
                        setTimeout(() => el.remove(), 680);
                    }
                    currentEasterEggs = currentEasterEggs.filter(e => e.key !== eggKey);

                    showMessage(`🥚 Du hast ${egg.name || "ein Osterei"} gefunden!`, "🐇 Oster-Event", "🐰");
                    queueMessage(`Hinweis: ${egg.hint || "gut versteckt"}`, "🐇 Oster-Event", "🐰");

                    const total = easterEventState.totalEggs || getEasterEggTotal();
                    if (easterEventState.collectedEggs.length >= total) {
                        easterEventState.completed = true;
                        queueMessage("🎉 Du hast ALLE Ostereier gefunden! Kehre zu Patrick zurück!", "🐇 Oster-Event", "🐰");
                    }

                    updateEasterUI(true);

                    const gameWin = document.getElementById("rpg-game-window");
                    if (gameWin) {
                        const spark = document.createElement("div");
                        spark.style.cssText = `position:absolute;left:${egg.x * TILE + 16}px;top:${egg.y * TILE}px;font-size:2.1rem;pointer-events:none;animation:easterSparkle 1s ease-out forwards;z-index:100;`;
                        spark.innerText = "✨";
                        gameWin.appendChild(spark);
                        parseEmojis(spark);
                        setTimeout(() => spark.remove(), 1000);
                    }

                    saveGame();
                }

                function updateEasterUI(pop = false) {
                    const easterUI = document.getElementById("easter-event-ui");
                    if (!easterUI) return;
                    normalizeEasterEventState();

                    if (!easterEventState.active || player.questState?.easterEvent === "completed") {
                        easterUI.style.display = "none";
                        easterUI.classList.remove("complete", "easter-pop", "hidden-for-player");
                        return;
                    }

                    const collected = easterEventState.collectedEggs.length;
                    const total = easterEventState.totalEggs || getEasterEggTotal();
                    const remaining = Math.max(0, total - collected);
                    const pct = total > 0 ? Math.min(100, (collected / total) * 100) : 0;

                    easterUI.style.display = "flex";
                    easterUI.style.setProperty("--easter-pct", pct + "%");
                    easterUI.classList.toggle("complete", easterEventState.completed);
                    if (pop) {
                        easterUI.classList.remove("easter-pop");
                        void easterUI.offsetWidth;
                        easterUI.classList.add("easter-pop");
                    }

                    const countEl = document.getElementById("easter-eggs-count");
                    const totalEl = document.getElementById("easter-eggs-total");
                    const fillEl = document.getElementById("easter-progress-fill");
                    const hintEl = document.getElementById("easter-event-hint");
                    if (countEl) countEl.innerText = collected;
                    if (totalEl) totalEl.innerText = total;
                    if (fillEl) fillEl.style.width = pct + "%";
                    if (hintEl) {
                        hintEl.innerText = easterEventState.completed
                            ? "✅ Alle Eier gefunden! Kehre zu Patrick zurück."
                            : `Noch ${remaining} ${remaining === 1 ? "Ei" : "Eier"} versteckt · Raum absuchen!`;
                    }
                    parseEmojis(easterUI);
                }

                function startEasterEvent() {
                    if (!player.questState) player.questState = {};
                    player.questState.easterEvent = "active";
                    easterEventState = {
                        active: true,
                        completed: false,
                        collectedEggs: [],
                        totalEggs: getEasterEggTotal()
                    };
                    spawnEasterEggs();
                    updateEasterUI(true);
                    saveGame();
                }

                function checkNearbyEasterEgg() {
                    normalizeEasterEventState();
                    if (!easterEventState.active || easterEventState.completed) return null;
                    for (const egg of currentEasterEggs) {
                        if (easterEventState.collectedEggs.includes(egg.key)) continue;
                        const dist = Math.abs(player.x - egg.x) + Math.abs(player.y - egg.y);
                        if (dist <= 1) {
                            const textEl = document.getElementById("interaction-text");
                            const iconEl = document.getElementById("interaction-icon");
                            if (textEl) textEl.innerText = "Sammeln";
                            if (iconEl) iconEl.innerText = egg.color || "🥚";
                            if (interactionHint) {
                                interactionHint.classList.remove("mode-attack", "mode-shop", "mode-talk", "mode-chest", "mode-default");
                                interactionHint.classList.add("visible", "mode-easter-egg");
                            }
                            return egg;
                        }
                    }
                    return null;
                }

                function updateEasterUIVisibility() {
                    const easterUI = document.getElementById("easter-event-ui");
                    if (!easterUI) return;
                    normalizeEasterEventState();
                    if (!easterEventState.active || player.questState?.easterEvent === "completed") {
                        easterUI.classList.remove("hidden-for-player");
                        return;
                    }
                    const viewportWidth = 27 * 32;
                    const playerScreenX = player.x * 32 - cameraX;
                    const playerScreenY = player.y * 32 - cameraY;
                    const isInUIArea = playerScreenY < 155 && playerScreenX > viewportWidth * 0.25 && playerScreenX < viewportWidth * 0.75;
                    easterUI.classList.toggle("hidden-for-player", isInUIArea);
                }

                function openPatrickEasterChoice(npc) {
                    if (typeof window.showChoice !== "function") return;
                    normalizeEasterEventState();
                    const questState = player.questState.easterEvent || null;

                    if (questState === null || questState === undefined) {
                        window.showChoice("Hallo! *hust* Ich bin Patrick, dein Ausbilder. Es ist Ostern und im Büro sind 10 Ostereier versteckt. Hilfst du mir bei der Suche?", [
                            { label: "Ja, ich helfe gerne!", value: "accept", hint: "🥚" },
                            { label: "Was bekomme ich dafür?", value: "reward", hint: "🎁" },
                            { label: "Nein, keine Zeit.", value: "decline", hint: "❌" }
                        ], npc.name, npc.sprite, (val) => {
                            if (val === "accept") {
                                startEasterEvent();
                                showMessage("Wunderbar! Ich habe dir eine neue Oster-Anzeige eingeblendet. Sie zeigt deinen Fortschritt zuverlässig an. 🐰", npc.name, npc.sprite);
                                queueMessage("Die Eier liegen im Büro (3), Flur (3), Kantine (2) und in der Zentrale (2).", npc.name, npc.sprite);
                            } else if (val === "reward") {
                                showMessage("Wenn du alle Eier findest, bringe ich dir den speziellen Skill **Oster-Flower-Power** bei! 🌸", npc.name, npc.sprite);
                                queueMessage("Sprich mich danach nochmal an, wenn du helfen möchtest.", npc.name, npc.sprite);
                            } else {
                                showMessage("Oh schade... Falls du es dir anders überlegst, bin ich hier.", npc.name, npc.sprite);
                            }
                        });
                        return;
                    }

                    if (questState === "active") {
                        const collected = easterEventState.collectedEggs.length;
                        const total = easterEventState.totalEggs;
                        if (easterEventState.completed) {
                            window.showChoice(`Unglaublich! Du hast alle ${total} Ostereier gefunden! Bist du bereit für deine Belohnung?`, [
                                { label: "Ja, her mit dem Skill!", value: "complete", hint: "🌸" }
                            ], npc.name, npc.sprite, (val) => {
                                if (val === "complete") {
                                    player.questState.easterEvent = "completed";
                                    easterEventState.active = false;
                                    easterEventState.completed = true;
                                    updateEasterUI();
                                    if (!player.unlockedSkills) player.unlockedSkills = ["tacker", "kaffee", "meeting"];
                                    if (!player.unlockedSkills.includes("oster_power")) {
                                        player.unlockedSkills.push("oster_power");
                                        showMessage("Du hast den exklusiven Skill **Oster-Flower-Power** gelernt! 🌸✨", "📋 System", "🌸");
                                        queueMessage("Dieser Skill heilt 50% deiner HP und fügt dem Gegner massiven Schaden zu!", "📋 System", "🌸");
                                    } else {
                                        player.gold += 200;
                                        updateHUD();
                                        showMessage("Du hast den Skill bereits! Hier sind 200 Gold als Oster-Bonus. 💰", npc.name, npc.sprite);
                                    }
                                    saveGame();
                                }
                            });
                        } else {
                            window.showChoice(`Du hast bisher ${collected} von ${total} Ostereiern gefunden. Noch ${Math.max(0, total - collected)} fehlen!`, [
                                { label: "Ich suche weiter!", value: "continue", hint: "🔍" },
                                { label: "Wo sind die Eier?", value: "hint", hint: "💡" }
                            ], npc.name, npc.sprite, (val) => {
                                if (val === "hint") {
                                    showMessage("Die Eier sind im Büro (3), Flur (3), Kantine (2) und in der Zentrale (2) versteckt.", npc.name, npc.sprite);
                                    queueMessage("Wenn du einen Spielstand lädst, erscheinen alle noch übrigen Eier wieder korrekt auf der aktuellen Map. 🥚✨", npc.name, npc.sprite);
                                } else {
                                    showMessage("Viel Erfolg! Die neue Anzeige sollte dir den Fortschritt sauber zeigen. 🐰", npc.name, npc.sprite);
                                }
                            });
                        }
                        return;
                    }

                    if (questState === "completed") {
                        showMessage("Danke nochmals für deine Hilfe bei der Ostersuche! Der Oster-Flower-Power Skill wird dir nützlich sein! 🌸🐰", npc.name, npc.sprite);
                    }
                }

                function hasAndConsumeItem(itemId, amount = 1) {
                    if (!player || !player.inventory) return false;
                    const it = player.inventory.find(i => i.id === itemId && i.count > 0);
                    if (!it) return false;
                    it.count -= amount;
                    if (it.count <= 0) player.inventory = player.inventory.filter(i => i !== it);
                    updateHUD();
                    return true;
                }

                // ===== HANDMADE DIALOG SYSTEM v4.4.0 =====
                let dialogVisualUpdateQueued = false;

                function queueDialogVisualUpdate(element = null) {
                    if (dialogVisualUpdateQueued) return;
                    dialogVisualUpdateQueued = true;
                    requestAnimationFrame(() => {
                        dialogVisualUpdateQueued = false;
                        const target = element || msgBox || document.getElementById("rpg-msg-box");
                        if (target) parseEmojis(target);
                    });
                }

                function renderRichText(text) {
                    const esc = String(text || "").replace(/[&<>]/g, ch => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;" }[ch]));
                    return esc
                        .replace(/\*\*(.+?)\*\*/g, '<span class="rich-bold">$1</span>')
                        .replace(/\b(\+\d+\s?(?:Gold|EXP|HP|MP|Max HP|Max MP))\b/g, '<span class="rich-good">$1</span>')
                        .replace(/(Achtung|Wichtig|Tipp|Hinweis|Quest)/gi, '<span class="rich-warn">$1</span>')
                        .replace(/(Fehler|verloren|besiegt|Gift|Schaden)/gi, '<span class="rich-bad">$1</span>');
                }

                function showMsgBox() {
                    if (!msgBox) return;
                    clearTimeout(msgBox._hideFallback);
                    clearTimeout(msgBox._choiceResolveTimer);
                    msgBox.classList.remove('dialog-v2', 'hiding');
                    msgBox.classList.add('dialog-v3');
                    if (!choiceActive) msgBox.classList.remove('choice-mode', 'choice-resolving', 'choice-count-1', 'choice-count-2', 'choice-count-3');
                    if (!msgBox.classList.contains('visible')) {
                        void msgBox.offsetWidth;
                        msgBox.classList.add('visible');
                    }
                }

                function hideMsgBox(forceImmediate = false) {
                    if (!msgBox) return;
                    clearTimeout(msgBox._hideFallback);
                    clearTimeout(msgBox._choiceResolveTimer);
                    const choiceBox = document.getElementById("msg-choice");
                    if (choiceBox) { choiceBox.classList.remove("visible"); choiceBox.innerHTML = ""; }
                    choiceActive = false;
                    choiceOptions = [];
                    choiceCallback = null;
                    msgBox.classList.remove('choice-mode', 'choice-resolving', 'choice-count-1', 'choice-count-2', 'choice-count-3');
                    if (!msgBox.classList.contains('visible')) return;
                    if (forceImmediate) {
                        msgBox.classList.remove('visible', 'hiding');
                        return;
                    }
                    msgBox.classList.add('hiding');
                    const finishHide = () => {
                        msgBox.classList.remove('visible', 'hiding', 'choice-mode', 'choice-resolving', 'choice-count-1', 'choice-count-2', 'choice-count-3');
                    };
                    msgBox.addEventListener('animationend', finishHide, { once: true });
                    msgBox._hideFallback = setTimeout(finishHide, 300);
                }

                function showMessage(text, speaker = "", portrait = "💬", callback = null) {
                    msgQueue.push({ text: String(text ?? ""), speaker, portrait, callback });
                    if (!msgLocked && !isTyping && !choiceActive) processMsg();
                }

                function queueMessage(text, speaker = "", portrait = "💬", callback = null) {
                    msgQueue.push({ text: String(text ?? ""), speaker, portrait, callback });
                }

                function processMsg() {
                    if (msgLocked || isTyping || choiceActive) return;

                    if (msgQueue.length === 0) {
                        msgLocked = false;
                        const cb = currentMsgCallback;
                        currentMsgCallback = null;

                        if (typeof cb === "function") {
                            cb();
                            if (choiceActive) return;
                            if (msgQueue.length > 0 && !isTyping && !msgLocked) {
                                setTimeout(processMsg, 0);
                                return;
                            }
                            if (gameState !== "MESSAGE") return;
                        }

                        if (gameState === "MESSAGE") {
                            hideMsgBox();
                            gameState = "MAP";
                            checkNearbyInteractables();
                        }
                        return;
                    }

                    msgLocked = true;
                    const choiceBox = document.getElementById("msg-choice");
                    if (choiceBox) { choiceBox.classList.remove("visible"); choiceBox.innerHTML = ""; }
                    if (msgBox) msgBox.classList.remove("choice-mode", "choice-resolving");

                    const msg = msgQueue.shift();
                    currentMsgCallback = typeof msg.callback === "function" ? msg.callback : null;
                    gameState = "MESSAGE";
                    if (interactionHint) interactionHint.classList.remove("visible");
                    if (typeTimer) clearTimeout(typeTimer);

                    const msgText = document.getElementById("msg-text");
                    const speakerEl = document.getElementById("msg-speaker");
                    const portraitEl = document.getElementById("msg-portrait");
                    if (msgText) msgText.textContent = "";
                    if (speakerEl) speakerEl.innerText = msg.speaker || "";
                    if (portraitEl) portraitEl.innerText = msg.portrait || "💬";

                    fullText = String(msg.text || "");
                    typeIndex = 0;
                    isTyping = true;
                    showMsgBox();
                    queueDialogVisualUpdate(portraitEl);
                    setTimeout(() => { msgLocked = false; typeChar(); }, 35);
                }

                function typeChar() {
                    const msgText = document.getElementById("msg-text");
                    if (!isTyping) return;
                    if (msgText) {
                        // Rich-Text + Emojis werden sofort gesetzt und per RAF gebündelt geparst.
                        // Dadurch erscheinen Farben/Emojis nicht erst am Ende.
                        msgText.classList.remove("text-preloaded");
                        msgText.innerHTML = renderRichText(fullText);
                        void msgText.offsetWidth;
                        msgText.classList.add("text-preloaded");
                        queueDialogVisualUpdate(msgText);
                    }
                    const _bvTextSpeed = (window.BV_SETTINGS && window.BV_SETTINGS.textSpeed) || "normal";
                    const _bvTextFactor = _bvTextSpeed === "instant" ? 0 : (_bvTextSpeed === "fast" ? 3.5 : (_bvTextSpeed === "slow" ? 10 : 7));
                    const readDelay = _bvTextSpeed === "instant" ? 40 : Math.min(650, Math.max(90, fullText.length * _bvTextFactor));
                    typeTimer = setTimeout(() => {
                        isTyping = false;
                    }, readDelay);
                }


                function advanceMsg() {
                    if (enterBlocked || msgLocked || choiceActive) return;
                    enterBlocked = true;
                    setTimeout(() => { enterBlocked = false; }, 220);
                    if (isTyping) {
                        if (typeTimer) clearTimeout(typeTimer);
                        isTyping = false;
                        const msgText = document.getElementById("msg-text");
                        if (msgText) {
                            msgText.innerHTML = renderRichText(fullText);
                            queueDialogVisualUpdate(msgText);
                        }
                        return;
                    }
                    processMsg();
                }

                function forceCloseMessage() {
                    if (typeTimer) clearTimeout(typeTimer);
                    isTyping = false;
                    msgLocked = false;
                    msgQueue = [];
                    currentMsgCallback = null;
                    fullText = "";
                    typeIndex = 0;
                    closeChoiceUI();
                    if (msgBox) hideMsgBox();
                    gameState = "MAP";
                    checkNearbyInteractables();
                }

                // BUGFIX: Textbox sauber schließen, wenn Map-Teleport, Screenwechsel oder Battle startet.
                // Anders als forceCloseMessage() setzt diese Funktion den State nicht zwangsweise zurück auf MAP.
                function closeMessageForInterrupt(nextState = null) {
                    if (typeTimer) { clearTimeout(typeTimer); typeTimer = null; }
                    isTyping = false;
                    msgLocked = false;
                    msgQueue = [];
                    currentMsgCallback = null;
                    fullText = "";
                    typeIndex = 0;
                    if (typeof closeChoiceUI === "function") closeChoiceUI();
                    if (msgBox) hideMsgBox(true);
                    if (interactionHint) interactionHint.classList.remove("visible");
                    if (nextState) gameState = nextState;
                }


                // Show boss pre-battle dialog in map before battle starts
                function showBossPreBattleDialog(npc, enemyData) {
                    const dialogs = enemyData.preBattleDialog;
                    if (!dialogs || dialogs.length === 0) {
                        startBattle(npc);
                        return;
                    }
                    
                    // Show each dialog line with the boss's name and sprite
                    // Last dialog triggers the battle directly
                    dialogs.forEach((dialog, index) => {
                        if (index === 0) {
                            showMessage(dialog, enemyData.name, enemyData.sprite);
                        } else if (index === dialogs.length - 1) {
                            // Last dialog - start battle after it's dismissed
                            queueMessage(dialog, enemyData.name, enemyData.sprite, () => {
                                startBattle(npc);
                            });
                        } else {
                            queueMessage(dialog, enemyData.name, enemyData.sprite);
                        }
                    });
                }

                // ===== MENU =====
                window.scrollMenuTabs = function (dir) {
                    const container = document.getElementById('menu-tabs-container');
                    if (container) {
                        container.style.overflowX = 'auto';
                        container.scrollBy({ left: dir * 140, behavior: 'smooth' });
                    }
                };

                window.openMenu = function () {
                    if (gameState !== "MAP") return;
                    gameState = "MENU";
                    const menuScreen = document.getElementById("rpg-menu-screen");
                    if (menuScreen) {
                        menuScreen.classList.remove("menu-closing", "menu-switching", "quit-active");
                        menuScreen.classList.add("active", "menu-opening", "menu-animating");
                        setTimeout(() => menuScreen.classList.remove("menu-opening", "menu-animating"), 460);
                    }
                    updateMenuStats();
                    updateTeamTab();
                    updateWorldMapTab();
                    updateMenuModeClass();
                    setTimeout(function () {
                        if (typeof window.renderSkillsTab === "function") window.renderSkillsTab();
                        if (typeof window.renderQuestTab === "function") window.renderQuestTab();
                        if (typeof window.renderAchievementTab === "function") window.renderAchievementTab();
                    }, 100);
                };

                function updateMenuModeClass() {
                    const menuScreen = document.getElementById("rpg-menu-screen");
                    const activeTab = document.querySelector(".menu-tab.active")?.dataset.tab || "status";
                    if (!menuScreen) return;
                    const ALL_MODES = ["menu-status-mode","menu-inventory-mode","menu-team-mode","menu-map-mode","menu-quest-mode","menu-achievement-mode","menu-skills-mode","menu-shift-mode","menu-settings-mode"];
                    ALL_MODES.forEach(m => menuScreen.classList.remove(m));
                    const modeMap = { status:"menu-status-mode", inventory:"menu-inventory-mode", team:"menu-team-mode", map:"menu-map-mode", quests:"menu-quest-mode", achievements:"menu-achievement-mode", skills:"menu-skills-mode", shift:"menu-shift-mode", settings:"menu-settings-mode" };
                    menuScreen.classList.add(modeMap[activeTab] || "menu-status-mode");
                }

                window.closeMenu = function (instant = false) {
                    if (!instant && typeof isQuitOptionsOpen === "function" && isQuitOptionsOpen()) return;
                    const menuScreen = document.getElementById("rpg-menu-screen");
                    const finishClose = () => {
                        if (menuScreen) menuScreen.classList.remove("active", "menu-closing", "menu-opening", "menu-switching", "menu-animating", "quit-active", "menu-status-mode", "menu-inventory-mode", "menu-team-mode", "menu-map-mode", "menu-quest-mode", "menu-achievement-mode", "menu-skills-mode", "menu-shift-mode", "menu-settings-mode");
                        showScreen("rpg-game-screen");
                        gameState = "MAP";
                        const gameWin = document.getElementById("rpg-game-window");
                        if (gameWin) {
                            gameWin.classList.remove("effect-particles", "effect-dim", "effect-windows");
                            if (currentMapId === "flur") gameWin.classList.add("effect-particles");
                            else if (currentMapId === "boss_office") gameWin.classList.add("effect-dim");
                            else if (currentMapId === "buero" || currentMapId === "zentrale") gameWin.classList.add("effect-windows");
                            else if (currentMapId === "kantine") gameWin.classList.add("effect-windows");
                        }
                    };
                    if (instant) finishClose();
                    else {
                        if (menuScreen) menuScreen.classList.add("menu-closing", "menu-animating");
                        setTimeout(finishClose, 230);
                    }
                };

                document.querySelectorAll(".menu-tab").forEach(tab => {
                    tab.addEventListener("click", () => {
                        const oldContent = document.querySelector(".menu-tab-content.active");
                        const content = document.getElementById("tab-" + tab.dataset.tab);
                        const menuScreen = document.getElementById("rpg-menu-screen");
                        if (oldContent === content) return;
                        if (menuScreen) {
                            menuScreen.classList.remove("menu-opening");
                            menuScreen.classList.add("menu-switching", "menu-animating");
                            setTimeout(() => menuScreen.classList.remove("menu-switching", "menu-animating"), 360);
                        }
                        if (oldContent) {
                            oldContent.classList.remove("menu-window-switch-in");
                            oldContent.classList.add("menu-window-switch-out");
                        }
                        setTimeout(() => {
                            document.querySelectorAll(".menu-tab").forEach(t => t.classList.remove("active"));
                            document.querySelectorAll(".menu-tab-content").forEach(c => c.classList.remove("active", "menu-window-switch-out", "menu-window-switch-in"));
                            tab.classList.add("active");
                            if (content) {
                                content.classList.add("active", "menu-window-switch-in");
                                setTimeout(() => content.classList.remove("menu-window-switch-in"), 320);
                            }
                            updateMenuModeClass();
                            if (tab.dataset.tab === "map") updateWorldMapTab();
                            if (tab.dataset.tab === "skills" && typeof window.renderSkillsTab === "function") window.renderSkillsTab();
                            if (tab.dataset.tab === "quests" && typeof window.renderQuestTab === "function") window.renderQuestTab();
                            if (tab.dataset.tab === "achievements" && typeof window.renderAchievementTab === "function") window.renderAchievementTab();
                        }, 110);
                    });
                });

                document.getElementById("rpg-menu-screen")?.addEventListener("wheel", (e) => {
                    const ms = document.getElementById("rpg-menu-screen");
                    if (ms?.classList.contains("menu-animating") || ms?.classList.contains("menu-switching") || ms?.classList.contains("menu-opening") || ms?.classList.contains("menu-closing")) {
                        e.preventDefault();
                    }
                }, { passive: false });

                function showMenuToast(text, type = "") {
                    const el = document.getElementById("menu-toast");
                    if (!el) return;

                    clearTimeout(el._t);
                    clearTimeout(el._hideT);

                    // Stabiler Toast-Reset: keine Layout-Verschiebung, Animation immer frisch.
                    el.classList.remove("show", "hiding", "good", "bad", "toast-replay", "toast-enter");
                    if (type) el.classList.add(type);
                    el.innerText = text;

                    // Reflow + RAF verhindert, dass Browser die Start-/End-States zusammenfasst.
                    void el.offsetWidth;
                    requestAnimationFrame(() => {
                        el.classList.add("show", "toast-enter");
                    });

                    const visibleTime = type === "bad" ? 2600 : 2200;
                    el._t = setTimeout(() => {
                        el.classList.remove("toast-enter");
                        el.classList.add("hiding");
                        el._hideT = setTimeout(() => {
                            el.classList.remove("show", "hiding", "good", "bad", "toast-replay", "toast-enter");
                        }, 460);
                    }, visibleTime);
                }

                function showMenuActionFx(text, kind = "heal") {
                    const menu = document.querySelector("#rpg-menu-screen .menu-window");
                    if (!menu) return;
                    const fx = document.createElement("div");
                    fx.className = "menu-fx-pop-v424 " + kind;
                    fx.innerText = text;
                    menu.appendChild(fx);
                    setTimeout(() => fx.remove(), 1250);
                }

                function useItemFromMenu(item) {
                    const canHealHp = item.heal && player.hp < player.maxHp;
                    const canHealMp = item.mpHeal && player.mp < player.maxMp;

                    if (!canHealHp && !canHealMp) {
                        showMenuToast("Du bist bereits voll (HP/MP).", "bad");
                        return;
                    }

                    item.count--;
                    if (item.count <= 0) player.inventory = player.inventory.filter(i => i !== item);

                    let healedHp = 0, healedMp = 0;
                    if (item.heal) { const old = player.hp; player.hp = Math.min(player.maxHp, player.hp + item.heal); healedHp = player.hp - old; }
                    if (item.mpHeal) { const old = player.mp; player.mp = Math.min(player.maxMp, player.mp + item.mpHeal); healedMp = player.mp - old; }

                    updateHUD();
                    updateMenuStats();

                    let msg = "Benutzt: " + item.name + " (";
                    if (healedHp) msg += `+${healedHp} HP`;
                    if (healedHp && healedMp) msg += ", ";
                    if (healedMp) msg += `+${healedMp} MP`;
                    msg += ")";
                    showMenuToast(msg, "good");
                    showMenuActionFx("✨ " + msg, "heal");
                }

                function updateMenuStats() {
                    const update = (id, val) => { const el = document.getElementById(id); if (el) el.innerText = val; };
                    const genderKey = player.gender || playerGender || "m";
                    const deptKey = player.dept || playerDept || "einkauf";
                    const statusSprite = player.sprite || GENDER_SPRITES[genderKey] || "🧑‍💼";
                    update("menu-player-name", player.name || "Held");
                    update("menu-portrait", statusSprite);
                    // Änderung: Im Titel keine Inline-Icons mehr. Das Icon bleibt nur links im Portrait.
                    update("menu-player-title", `${GENDER_TITLES[genderKey] || "Auszubildender"} • ${DEPT_NAMES[deptKey] || deptKey}`);
                    const statusPortrait = document.getElementById("menu-portrait");
                    if (statusPortrait && typeof parseEmojis === "function") parseEmojis(statusPortrait);
                    update("menu-hp", player.hp + "/" + player.maxHp);
                    update("menu-mp", player.mp + "/" + player.maxMp);
                    update("menu-atk", player.atk);
                    update("menu-def", player.def);
                    update("menu-gold", player.gold);
                    update("menu-exp", player.exp + " / " + player.expNext);
                    update("menu-lvl", player.lvl);

                    const expBar = document.getElementById("menu-exp-bar");
                    if (expBar) expBar.style.width = (player.exp / player.expNext * 100) + "%";

                    const inv = document.getElementById("menu-inventory");
                    if (!inv) return;
                    inv.innerHTML = "";

                    if (player.inventory.length === 0) {
                        inv.innerHTML = "<div class='menu-item empty'><span class='menu-item-icon'>📭</span><span class='menu-item-name'>Inventar leer</span><span class='menu-item-meta'>Sammle Items aus Shops und Kisten.</span></div>";
                        return;
                    }

                    player.inventory.forEach(item => {
                        const parts = item.name.split(" ");
                        const icon = parts[0];
                        const name = parts.slice(1).join(" ") || item.name;

                        const el = document.createElement("div");
                        el.className = "menu-item";

                        const usable = (item.heal || item.mpHeal);
                        const isBoost = item.atkBoost || item.defBoost || item.hpBoost || item.mpBoost;
                        if (usable) el.classList.add("usable");
                        if (isBoost) el.classList.add("boost");

                        let meta = [];
                        if (item.heal) meta.push(`HP +${item.heal}`);
                        if (item.mpHeal) meta.push(`MP +${item.mpHeal}`);
                        if (item.atkBoost) meta.push(`ATK +${item.atkBoost}`);
                        if (item.defBoost) meta.push(`DEF +${item.defBoost}`);
                        if (item.hpBoost) meta.push(`Max HP +${item.hpBoost}`);
                        if (item.mpBoost) meta.push(`Max MP +${item.mpBoost}`);
                        if (meta.length === 0) meta.push("Quest-/Sammelitem");

                        el.innerHTML = `
                            <span class="menu-item-icon">${icon}</span>
                            <span class="menu-item-name">${name}</span>
                            <span class="menu-item-count">x${item.count}</span>
                            <span class="menu-item-meta">${meta.join(" • ")}</span>
                            ${usable ? "<button class='menu-item-action'>Nutzen</button>" : (isBoost ? "<button class='menu-item-action'>Passiv</button>" : "")}
                        `;

                        if (usable) {
                            el.style.cursor = "pointer";
                            el.onclick = () => useItemFromMenu(item);
                            const btn = el.querySelector('.menu-item-action');
                            if (btn) btn.onclick = (e) => { e.stopPropagation(); useItemFromMenu(item); };
                        }

                        inv.appendChild(el);
                    });

                    parseEmojis(inv);
                }

