                function drawMenuCurrentMap() {
                    const canvas = document.getElementById("menu-current-map-canvas");
                    if (!canvas || !currentMap || currentMap.length === 0) return;
                    const ctx = canvas.getContext("2d");
                    const rows = currentMap.length;
                    const cols = currentMap[0]?.length || 1;
                    const scale = Math.max(6, Math.min(18, Math.floor(Math.min(620 / cols, 340 / rows))));
                    canvas.width = cols * scale;
                    canvas.height = rows * scale;
                    ctx.clearRect(0, 0, canvas.width, canvas.height);
                    for (let y = 0; y < rows; y++) {
                        for (let x = 0; x < cols; x++) {
                            const tile = currentMap[y]?.[x] ?? 0;
                            const tileData = TILES[tile] || TILES[0];
                            let color = tileData.block ? "#203044" : "#58708a";
                            if (tileData.name?.includes("door")) color = "#e9c949";
                            else if (tile === 4 || tile === 5 || tile === 13) color = "#6d82a0";
                            else if (tile === 3) color = "#2e7d51";
                            ctx.fillStyle = color;
                            ctx.fillRect(x * scale, y * scale, scale, scale);
                        }
                    }
                    // Grid subtle
                    ctx.strokeStyle = "rgba(255,255,255,.08)";
                    ctx.lineWidth = 1;
                    for (let x = 0; x <= cols; x++) { ctx.beginPath(); ctx.moveTo(x*scale,0); ctx.lineTo(x*scale,rows*scale); ctx.stroke(); }
                    for (let y = 0; y <= rows; y++) { ctx.beginPath(); ctx.moveTo(0,y*scale); ctx.lineTo(cols*scale,y*scale); ctx.stroke(); }
                    currentChests.forEach(chest => {
                        if (chest.opened) return;
                        ctx.fillStyle = chest.type === "rare" ? "#d946ef" : "#f59e0b";
                        ctx.fillRect(chest.x * scale + scale*.18, chest.y * scale + scale*.18, scale*.64, scale*.64);
                    });
                    npcs.forEach(npc => {
                        ctx.fillStyle = npc.type === "enemy" ? "#ef4444" : (npc.type === "shop" || npc.type === "skillshop" ? "#facc15" : "#38bdf8");
                        ctx.beginPath();
                        ctx.arc(npc.x * scale + scale/2, npc.y * scale + scale/2, Math.max(2.5, scale*.36), 0, Math.PI*2);
                        ctx.fill();
                    });
                    ctx.fillStyle = "#22c55e";
                    ctx.beginPath();
                    ctx.arc(player.x * scale + scale/2, player.y * scale + scale/2, Math.max(3.5, scale*.45), 0, Math.PI*2);
                    ctx.fill();
                    ctx.strokeStyle = "#fff";
                    ctx.lineWidth = 2;
                    ctx.stroke();
                }

                // ===== SAVE/LOAD =====
                window.saveGame = function () {
                    // Ensure player object has the latest gender and dept
                    player.gender = playerGender;
                    player.dept = playerDept;
                    if (!player.unlockedSkills) player.unlockedSkills = [];
                    if (!player.questState) player.questState = {};
                    if (typeof normalizeEasterEventState === "function") normalizeEasterEventState();

                    const saveData = {
                        version: "6.0.0",
                        // Top-level metadata for compatibility with older save readers
                        name: player.name,
                        gender: playerGender,
                        dept: playerDept,
                        player: player,
                        defeatedEnemies: Array.from(defeatedEnemies),
                        openedChests: Array.from(openedChests),
                        metNPCs: metNPCs,
                        currentMapId: currentMapId,
                        // Spielerposition + Blickrichtung explizit speichern,
                        // damit sie beim Laden wiederhergestellt werden kann.
                        playerPos: { x: player.x, y: player.y, facing: player.facing || "right" },
                        battleCount: battleCount,
                        chestCount: chestCount,
                        unlockedSkills: player.unlockedSkills,
                        questState: player.questState,
                        easterEventState: easterEventState,
                        achievements: localStorage.getItem('bv_achievements') || '{}',
                        timestamp: Date.now()
                    };

                    try {
                        console.log("[BüroVersum] Saving game:", saveData);
                        localStorage.setItem('bueroversum_save', JSON.stringify(saveData));
                        showMenuToast("💾 Spiel gespeichert!", "good");
                        showMenuActionFx("💾 Gespeichert", "save");
                    } catch (e) {
                        showMenuToast("❌ Speichern fehlgeschlagen!", "bad");
                        console.error("[BüroVersum] Save error:", e);
                    }
                };

                window.loadGame = function () {
                    const saved = localStorage.getItem('bueroversum_save');
                    if (!saved) { showMenuToast("❌ Kein Spielstand gefunden!", "bad"); return; }

                    try {
                        const data = JSON.parse(saved);
                        console.log("[BüroVersum] Loaded save:", data);

                        // Restore player object with all properties
                        player = data.player || {};
                        window.player = player; // BUGFIX: globale Shop-Referenz nach Laden aktualisieren
                        player.name = player.name || data.name || "Held";
                        player.unlockedSkills = data.unlockedSkills || player.unlockedSkills || ["tacker", "kaffee", "meeting"];

                        // Restore gender and department
                        playerGender = data.gender || player.gender || "m";
                        playerDept = data.dept || player.dept || "einkauf";

                        // Ensure player sprite is correct
                        player.sprite = player.sprite || GENDER_SPRITES[playerGender];
                        player.gender = playerGender;
                        player.dept = playerDept;

                        // Restore game state
                        defeatedEnemies = new Set(data.defeatedEnemies || []);
                        openedChests = new Set(data.openedChests || []);
                        metNPCs = data.metNPCs || [];
                        battleCount = data.battleCount || 0;
                        chestCount = data.chestCount || 0;
                        
                        // Restore quest state (explicitly from top-level or player object)
                        player.questState = data.questState || player.questState || {};

                        // Restore achievements from save
                        if (data.achievements) {
                            try { localStorage.setItem('bv_achievements', data.achievements); } catch (e) {}
                            if (typeof window.resetAchievementCache === 'function') window.resetAchievementCache();
                        }

                        // Spielerposition für das Laden der Map vormerken
                        // (Fallback auf player.x/player.y bei alten Spielständen).
                        const _ldX = (data.playerPos && typeof data.playerPos.x === "number")
                            ? data.playerPos.x : player.x;
                        const _ldY = (data.playerPos && typeof data.playerPos.y === "number")
                            ? data.playerPos.y : player.y;
                        const _ldFacing = (data.playerPos && data.playerPos.facing)
                            ? data.playerPos.facing : (player.facing || "right");
                        if (typeof _ldX === "number" && typeof _ldY === "number") {
                            pendingLoadPos = { mapId: data.currentMapId || "buero", x: _ldX, y: _ldY, facing: _ldFacing };
                        } else {
                            pendingLoadPos = null;
                        }

                        // Restore Easter Event State
                        if (data.easterEventState) {
                            easterEventState = data.easterEventState;
                        } else if (player.easterEventState) {
                            easterEventState = player.easterEventState;
                        }
                        if (typeof normalizeEasterEventState === "function") normalizeEasterEventState();
                        updateEasterUI();

                        // Update ALL UI elements with correct name and sprite
                        const update = (id, val) => { const el = document.getElementById(id); if (el) el.innerText = val; };
                        update("hud-player-name", player.name);
                        update("player-sprite-name", player.name);
                        update("battle-player-name", player.name);
                        update("menu-player-name", player.name);
                        update("vs-player-name", player.name);

                        // Update sprites everywhere
                        update("hud-portrait", player.sprite);
                        update("menu-portrait", player.sprite);
                        update("battle-portrait", player.sprite);
                        update("vs-player-sprite", player.sprite);

                        const spriteBody = document.querySelector("#rpg-player .sprite-body");
                        if (spriteBody) spriteBody.innerText = player.sprite;

                        const battlePortrait = document.querySelector(".player-portrait-battle");
                        if (battlePortrait) battlePortrait.innerText = player.sprite;

                        // Update player title in menu
                        update("menu-player-title", GENDER_TITLES[playerGender] + " - " + DEPT_NAMES[playerDept]);

                        // Close any open menus and start transition when loading
                        if (gameState === "MENU") closeMenu(true);
                        if (mapTrans) {
                            const transText = mapTrans.querySelector('.transition-text');
                            if (transText) transText.innerText = MAPS[data.currentMapId]?.name || 'Laden...';
                        }
                        startMapTransition();

                        // After transition, show game screen and load map (with normal transition effects)
                        setTimeout(() => {
                            currentEnemy = null;
                            showScreen("rpg-game-screen");
                            loadMap(data.currentMapId || "buero", true);
                            gameState = "MAP";
                            startCameraLoop();
                            _hudGoldCurrent = player.gold;
                            updateHUD();
                            updateMenuStats();
                            // ARENA PATCH: EASTER RESPAWN AFTER LOAD
                            // loadMap(true) lädt die Map verzögert; deshalb Easter-Eier danach nochmal sicher spawnen.
                            setTimeout(() => {
                                if (typeof refreshEasterEventAfterMapLoad === "function") refreshEasterEventAfterMapLoad();
                                else { spawnEasterEggs(); updateEasterUI(); }
                            }, 720);
                            updateEasterUI();
                            showMenuToast("📂 Spielstand geladen!", "good");
                        }, 550);

                    } catch (e) {
                        showMenuToast("❌ Laden fehlgeschlagen!", "bad");
                        console.error("Load error:", e);
                    }
                };

                // ===== SHOP =====
                function openShop() {
                    gameState = "SHOP";
                    window.player = player; // BUGFIX: aktuelles Spielerobjekt für neues Shop-UI bereitstellen
                    const gameWin = document.getElementById("rpg-game-window");
                    if (gameWin) gameWin.classList.remove("effect-particles", "effect-dim", "effect-windows");
                    // PATCHED: Neues Shop-UI
                    showScreen("rpg-shop-screen");
                    if (typeof renderNewShopUI === "function") renderNewShopUI();
                    else if (typeof window.renderNewShopUI === "function") window.renderNewShopUI();
                }

                function renderShopItems() {
                    // PATCHED: Wird von renderNewShopUI übernommen
                    if (typeof renderNewShopUI === "function") renderNewShopUI();
                }

                function buyItem(item) {
                    const keeperText = document.getElementById("shop-keeper-text");

                    if (player.gold < item.price) {
                        if (keeperText) keeperText.innerText = '"Nicht genug Gold!"';
                        return;
                    }

                    player.gold -= item.price;
                    const goldEl = document.getElementById("shop-gold");
                    if (goldEl) goldEl.innerText = player.gold;

                    const shopItems = document.querySelectorAll(".shop-item");
                    shopItems.forEach(el => {
                        if (el.querySelector(".shop-item-name")?.innerText === item.name) {
                            el.classList.add("purchased");
                            setTimeout(() => el.classList.remove("purchased"), 500);
                        }
                    });

                    renderShopItems();

                    if (item.heal) {
                        const existing = player.inventory.find(i => i.id === item.id);
                        if (existing) existing.count++;
                        else player.inventory.push({ id: item.id, name: item.icon + " " + item.name, heal: item.heal, mpHeal: item.mpHeal || 0, count: 1 });
                        if (keeperText) keeperText.innerText = `"${item.name} - gute Wahl!"`;
                    } else if (item.atkBoost) {
                        player.atk += item.atkBoost;
                        if (keeperText) keeperText.innerText = `"Angriff +${item.atkBoost}!"`;
                    } else if (item.defBoost) {
                        player.def += item.defBoost;
                        if (keeperText) keeperText.innerText = `"Verteidigung +${item.defBoost}!"`;
                    } else if (item.hpBoost) {
                        player.maxHp += item.hpBoost;
                        player.hp = player.maxHp;
                        if (keeperText) keeperText.innerText = `"Max HP +${item.hpBoost}!"`;
                    } else if (item.mpBoost) {
                        player.maxMp += item.mpBoost;
                        player.mp = player.maxMp;
                        if (keeperText) keeperText.innerText = `"Max MP +${item.mpBoost}!"`;
                    }

                    updateHUD();
                }

                window.closeShop = function () {
                    if (currentEnemy && currentEnemy.isEditorTest) {
                            showScreen("rpg-battle-editor-screen");
                        } else {
                            showScreen("rpg-game-screen");
                        }
                    gameState = "MAP";
                    // Restore map effects when closing shop
                    const gameWin = document.getElementById("rpg-game-window");
                    if (gameWin) {
                        gameWin.classList.remove("effect-particles", "effect-dim", "effect-windows");
                        if (currentMapId === "flur") gameWin.classList.add("effect-particles");
                        else if (currentMapId === "boss_office") gameWin.classList.add("effect-dim");
                        else if (currentMapId === "buero" || currentMapId === "zentrale") gameWin.classList.add("effect-windows");
                        else if (currentMapId === "kantine") gameWin.classList.add("effect-windows");
                    }
                };

