                window.closeComputer = function() {
                    const modal = document.getElementById("computer-modal");
                    if (modal) {
                        modal.classList.remove("active");
                        // Close all apps
                        document.querySelectorAll('.app-window').forEach(app => app.classList.remove('active'));
                        // Close start menu with animation
                        const startMenu = document.getElementById('start-menu');
                        if (startMenu) {
                            startMenu.classList.remove('active');
                            startMenu.classList.remove('closing');
                        }
                        currentOpenApp = null;
                        if (computerTimeInterval) clearInterval(computerTimeInterval);
                        gameState = "MAP";
                        checkNearbyInteractables();
                    }
                };

                window.toggleStartMenu = function() {
                    const menu = document.getElementById("start-menu");
                    if (!menu) return;
                    
                    if (menu.classList.contains("active")) {
                        // Close animation
                        menu.classList.add("closing");
                        menu.classList.remove("active");
                        setTimeout(() => {
                            menu.classList.remove("closing");
                        }, 300);
                    } else {
                        // Open animation
                        menu.classList.remove("closing");
                        menu.classList.add("active");
                    }
                };
                
                // Close start menu when clicking outside
                document.addEventListener('click', function(e) {
                    const startMenu = document.getElementById('start-menu');
                    const startBtn = document.querySelector('.taskbar-start');
                    if (startMenu && startMenu.classList.contains('active')) {
                        if (!startMenu.contains(e.target) && !startBtn.contains(e.target)) {
                            startMenu.classList.add('closing');
                            startMenu.classList.remove('active');
                            setTimeout(() => {
                                startMenu.classList.remove('closing');
                            }, 300);
                        }
                    }
                });

