                        // Buy item in window browser
                        function buyItemInWindow(itemId, winElement) {
                            const item = BROWSER_SHOP_ITEMS.find(i => i.id === itemId);
                            if (!item) return;
                            
                            const content = winElement.querySelector('#browser-content');
                            const playerGold = player && player.gold ? player.gold : 0;
                            
                            if (!player) {
                                showWindowShopMessage("Fehler: Spieler nicht gefunden!", "error", winElement);
                                return;
                            }
                            
                            if (player.gold < item.price) {
                                showWindowShopMessage(`Nicht genug Gold! Du brauchst ${item.price} Gold.`, "error", winElement);
                                return;
                            }
                            
                            // Deduct gold
                            player.gold -= item.price;
                            
                            // Apply item effects
                            if (item.heal) {
                                const existing = player.inventory.find(i => i.id === item.id);
                                if (existing) existing.count++;
                                else player.inventory.push({ id: item.id, name: item.icon + " " + item.name, heal: item.heal, mpHeal: item.mpHeal || 0, count: 1 });
                            } else if (item.atkBoost) {
                                player.atk += item.atkBoost;
                            } else if (item.defBoost) {
                                player.def += item.defBoost;
                            } else if (item.hpBoost) {
                                player.maxHp += item.hpBoost;
                                player.hp += item.hpBoost;
                            } else if (item.mpBoost) {
                                player.maxMp += item.mpBoost;
                                player.mp += item.mpBoost;
                            }
                            
                            // Update game HUD
                            if (typeof updateHUD === 'function') updateHUD();
                            
                            // Show success message
                            showWindowShopMessage(`✅ ${item.name} gekauft!`, "success", winElement);
                            
                            // Refresh shop
                            setTimeout(() => {
                                loadBrowserPage('www.bueroshop.de', winElement);
                            }, 500);
                        }
                        
                        // Show shop message in window
